LGB_REQUIRE_MINUTE_PRIMARY_EVAL = True

# [REGRESSION-CS] 回归训练目标：当日横截面变换标签。
#   "zscore"    -> 当日 z-score（去市场共同成分，保留行业/个股相对强弱）
#   "rank"      -> 当日百分位秩映射到 [-1, 1]（对极端值更稳健，与收益0.3截断兼容）
#   "rankgauss" -> 当日横截面分位映射到标准正态（rank-gauss / Blom 变换）：
#                  排序与 z-score 等价（单调），但把连续标签平滑为近似正态，
#                  压缩不可预测噪声、降低模型过拟合；比硬分层信息损失更小。
# 注意：原始 3 日收益 atr_return_label 仍保留，用于回测、分钟缓存评估与权重计算。
REGRESSION_CS_LABEL_MODE = "zscore"   # [REGRESSION] 保留幅度（28.log rank1真实0.0216的标签）；rankgauss压缩幅度→rank1掉到0.010
REGRESSION_CS_LABEL_COL = {
    "zscore": "cs_z_label",
    "rank": "cs_rank_label",
    "rankgauss": "cs_rankgauss_label",
}.get(REGRESSION_CS_LABEL_MODE, "cs_rankgauss_label")
# [REGRESSION-CS] z-score 标签按日截断到 ±REGRESSION_CS_Z_CLIP，防止极端收益主导模型
REGRESSION_CS_Z_CLIP = 3.0
# [REGRESSION-CS] 原始3日收益截断上限（供权重函数判断"头部饱和"使用，与标签生成一致）
# [v16] cap 0.50->0.30 回退：v16实测测试RankIC=0.0108(t=0.96不显著) vs regress_52(cap0.30)的0.0300(t=2.63显著)。
#   cap0.50让MSE放大极端梯度->模型过度追逐极端票，验证集(牛市)学得好、测试集(调整市)失效。
#   印证rankgauss_3教训(cap0.50崩NDCG)，zscore下同样崩。
REGRESSION_LABEL_CAP = 0.30
