# [v70] 辅助函数：按月生成交易日范围（首末交易日），供下方MONTH_TRAIN/VAL字典构建使用
def _month_range(ym_str, first_day=1, last_day=31):
    """返回(首日, 末日)日期字符串元组。first_day/last_day用于微调边界避免跨月。"""
    y, m = int(ym_str[:4]), int(ym_str[4:6])
    import calendar
    last = min(last_day, calendar.monthrange(y, m)[1])
    return (f"{y:04d}-{m:02d}-{first_day:02d}", f"{y:04d}-{m:02d}-{last:02d}")

def _build_month_dicts():
    """自动构建全部涉及月份的TRAIN/VAL日期字典（基于日历推断，无需手工查表）。"""
    _train_d, _val_d = {}, {}
    _all_months = [
        # 2023 H2
        "202306", "202307", "202308", "202309", "202310", "202311", "202312",
        # 2024
        "202401", "202402", "202403", "202404", "202405", "202406",
        "202407", "202408", "202409", "202410", "202411", "202412",
        # 2025
        "202501", "202502", "202503", "202504", "202505", "202506", "202507",
    ]
    for ym in _all_months:
        y, m = int(ym[:4]), int(ym[4:])
        import calendar as _cal
        last_day = _cal.monthrange(y, m)[1]
        # TRAIN口径：避开月初第一天和月末最后一天（边界保护）
        fd = min(4, last_day)
        ld = max(last_day - 4, fd)
        _train_d[ym] = (f"{y:04d}-{m:02d}-{fd:02d}", f"{y:04d}-{m:02d}-{ld:02d}")
        # VAL口径：全月
        _val_d[ym] = (f"{y:04d}-{m:02d}-01", f"{y:04d}-{m:02d}-{last_day:02d}")
    return _train_d, _val_d

_MTRAIN_TMP, _MVAL_TMP = _build_month_dicts()

MFOLD_SWAP_MONTH_TRAIN = _MTRAIN_TMP
MFOLD_SWAP_MONTH_VAL = _MVAL_TMP

