def print_rank_robust_stats(rank_returns):
    """打印每日Rank1～Rank5单只股票的收益分布。"""
    logger.info("")
    logger.info("[HISTOGRAM] Rank1～Rank5收益分布直方图:")
    for rank_position in sorted(rank_returns):
        all_returns = rank_returns[rank_position]
        if len(all_returns) > 0:
            logger.info(f"  Rank-{rank_position}收益分布:")
            create_ascii_histogram(all_returns, bins=12)
            logger.info("")

    logger.info("")
    logger.info("💡 推荐对比指标:")
    logger.info("  1. Winsorized均值 - 去除极端值影响，更稳健")
    logger.info("  2. 夏普比率 - 风险调整后收益，更全面")
    logger.info("  3. 传统均值 - 作为参考，但注意极端值影响")
    logger.info("")


def create_ascii_histogram(values, bins=15):
    """创建ASCII直方图"""
    if len(values) == 0:
        return

    # 计算直方图数据
    hist, bin_edges = np.histogram(values, bins=bins)
    max_count = hist.max()

    logger.info(f"      区间          频数  直方图")
    logger.info(f"      " + "-"*45)

    for i, count in enumerate(hist):
        # 格式化区间显示
        left_edge = bin_edges[i]
        right_edge = bin_edges[i+1]
        interval = f"[{left_edge:6.3f},{right_edge:6.3f})"

        # 创建条形图
        if max_count > 0:
            bar_length = int(count / max_count * 30)  # 30字符最大宽度
            bar = "█" * bar_length
        else:
            bar = ""

        logger.info(f"      {interval} {count:3d}   {bar}")

def calculate_ndcg_at_k(y_true, y_score, k=5):
    """
    计算NDCG@k (Normalized Discounted Cumulative Gain) - 使用真实收益率

    Args:
        y_true: 真实相关性得分（推荐使用收益率）
        y_score: 预测得分
        k: 截断位置

    Returns:
        NDCG@k 值
    """
    # 获取排序后的索引
    sorted_indices = np.argsort(y_score)[::-1]  # 降序排列
    sorted_true_relevance = y_true[sorted_indices[:k]]

    # 计算DCG@k
    dcg = 0.0
    for i, relevance in enumerate(sorted_true_relevance):
        if i == 0:
            dcg += relevance
        else:
            dcg += relevance / math.log2(i + 1)

    # 计算IDCG@k (理想DCG)
    ideal_sorted_relevance = np.sort(y_true)[::-1][:k]
    idcg = 0.0
    for i, relevance in enumerate(ideal_sorted_relevance):
        if i == 0:
            idcg += relevance
        else:
            idcg += relevance / math.log2(i + 1)

    # 计算NDCG@k
    if idcg == 0:
        return 0.0
    return dcg / idcg


def calculate_adjusted_ndcg_at_k(y_true, y_score, k=5):
    """
    [强化] 改进的NDCG计算，解决负收益和量纲问题

    主要改进：
    1. 收益率标准化，解决量纲敏感性问题
    2. 负收益阈值处理，避免过度惩罚
    3. 基于百分位的稳健归一化

    Args:
        y_true: 真实收益率数组
        y_score: 预测得分数组
        k: 截断位置

    Returns:
        float: 改进的NDCG@k 值
    """
    import numpy as np

    # 输入验证
    if len(y_true) == 0 or len(y_score) == 0 or len(y_true) != len(y_score):
        return 0.0

    if k <= 0:
        return 0.0

    y_true = np.array(y_true, dtype=float)
    y_score = np.array(y_score, dtype=float)

    # [WRENCH] 改进1：收益率标准化（z-score）
    if y_true.std() > 1e-8:  # 避免除零
        normalized_returns = (y_true - y_true.mean()) / y_true.std()
    else:
        # 如果标准差为0，直接设为0
        normalized_returns = np.zeros_like(y_true)

    # [WRENCH] 改进2：负收益阈值处理
    # 使用30%分位数作为最小值阈值，避免过度惩罚极端负收益
    min_threshold = np.percentile(normalized_returns, 30)
    normalized_returns = np.maximum(normalized_returns, min_threshold)

    # [WRENCH] 改进3：确保有足够的正值用于有意义的排序
    # 如果大部分值都是负数，进行平移
    if normalized_returns.mean() < 0:
        normalized_returns = normalized_returns - normalized_returns.mean()

    # 使用原始NDCG逻辑计算标准化的结果
    return calculate_ndcg_at_k(normalized_returns, y_score, k)


def _calc_max_drawdown(returns):
    rets = np.asarray(returns, dtype=float)
    if rets.size == 0:
        return 0.0
    cumulative = np.cumprod(1.0 + rets)
    running_peak = np.maximum.accumulate(cumulative)
    drawdowns = cumulative / np.maximum(running_peak, 1e-12) - 1.0
    return float(np.min(drawdowns)) if drawdowns.size > 0 else 0.0


def _hac_tstat(x, lag=2):
    """Newey-West HAC t统计量：处理3日收益序列的重叠自相关（相邻信号日重叠2天）。

    对日度超额/head-gap序列，普通t统计量会把显著性夸大~sqrt(3)倍；
    用Bartlett核HAC方差（默认lag=2）得到稳健t值，是早停/评估的统计显著性基准。
    """
    x = np.asarray(x, dtype=float)
    x = x[np.isfinite(x)]
    n = int(len(x))
    if n < 20:
        return np.nan
    mu = float(np.mean(x))
    e = x - mu
    var0 = float(np.mean(e * e))
    var = var0
    for l in range(1, int(lag) + 1):
        if l >= n:
            break
        w = 1.0 - l / (lag + 1.0)
        gam = float(np.mean(e[l:] * e[:-l]))
        var += 2.0 * w * gam
    var = max(var, 1e-12)
    return float(mu / np.sqrt(var / n))


def _build_or_load_validation_minute_cache_binary_legacy(
    val_data_raw: Optional[pd.DataFrame],
    selection_data_raw: Optional[pd.DataFrame] = None,
    test_data_raw: Optional[pd.DataFrame] = None,
    holding_days: int = 3,
    minute_data_path: str = "../local_data/minute/",
    build_if_missing: bool = False,
) -> Optional[pd.DataFrame]:
    if val_data_raw is None or len(val_data_raw) == 0:
        return None

    from rqalpha_minute_datasource.strategy_backtest_lead_fusion_rank_binary_v2 import (
        StrategyConfig,
        StrategyType,
        build_minute_trade_cache,
        get_minute_trade_cache_rule_signature,
    )

    context_frames = [df for df in [val_data_raw, selection_data_raw, test_data_raw] if df is not None and len(df) > 0]
    if not context_frames:
        return None

    target_rows = val_data_raw.copy()
    context_rows = pd.concat(context_frames, ignore_index=True)
    for df in (target_rows, context_rows):
        df['date'] = pd.to_datetime(df['date'])

    trading_dates = sorted(pd.to_datetime(context_rows['date']).dt.date.unique().tolist())
    cfg = StrategyConfig(
        strategy_type=StrategyType.TOP_1,
        stock_count=1,
        enable_dynamic_rank_switch=False,
        holding_days=int(holding_days),
        max_concurrent_positions=1,
        fixed_position_pct=1.0,
        position_schedule=[1.0]
    )
    rule_sig = get_minute_trade_cache_rule_signature(cfg)

    cache_dir = Path(__file__).resolve().parent / "results" / "minute_eval_cache"
    start_str = pd.to_datetime(target_rows['date']).min().strftime('%Y%m%d')
    end_str = pd.to_datetime(target_rows['date']).max().strftime('%Y%m%d')
    cache_path = cache_dir / f"val_minute_cache_{start_str}_{end_str}_{rule_sig}.parquet"

    logger.info(
        f"[MINUTE_CACHE] 二分类脚本目标验证集分钟缓存: rows={len(target_rows):,}, "
        f"dates={target_rows['date'].nunique()}, path={cache_path}"
    )
    if cache_path.exists():
        logger.info(f"[MINUTE_CACHE] 命中已有缓存: {cache_path}")
        return pd.read_parquet(cache_path)

    shard_pattern = re.compile(
        rf"^val_minute_cache_(\d{{8}})_(\d{{8}})_{re.escape(rule_sig)}\.parquet$"
    )
    shard_files = []
    for path in cache_dir.glob(f"val_minute_cache_*_{rule_sig}.parquet"):
        match = shard_pattern.match(path.name)
        if not match:
            continue
        shard_start = pd.to_datetime(match.group(1))
        shard_end = pd.to_datetime(match.group(2))
        if shard_end < pd.to_datetime(start_str) or shard_start > pd.to_datetime(end_str):
            continue
        shard_files.append((shard_start, shard_end, path))

    if shard_files:
        shard_files.sort(key=lambda x: (x[0], x[1], str(x[2])))
        logger.info(f"[MINUTE_CACHE] 二分类脚本尝试拼接 {len(shard_files)} 个分钟缓存分片...")
        shard_frames = []
        for _, _, shard_path in shard_files:
            logger.info(f"[MINUTE_CACHE] 读取分片: {shard_path.name}")
            shard_df = pd.read_parquet(shard_path)
            shard_df['date'] = pd.to_datetime(shard_df['date'])
            shard_df = shard_df[
                (shard_df['date'] >= pd.to_datetime(start_str)) &
                (shard_df['date'] <= pd.to_datetime(end_str))
            ].copy()
            shard_frames.append(shard_df)

        if shard_frames:
            merged_df = pd.concat(shard_frames, ignore_index=True)
            merged_df = (
                merged_df
                .sort_values(['date', 'stock_code'])
                .drop_duplicates(['date', 'stock_code'], keep='last')
                .reset_index(drop=True)
            )
            expected_dates = set(pd.to_datetime(target_rows['date']).dt.normalize().unique().tolist())
            actual_dates = set(pd.to_datetime(merged_df['date']).dt.normalize().unique().tolist())
            missing_dates = sorted(expected_dates - actual_dates)
            if not missing_dates:
                logger.info(
                    f"[MINUTE_CACHE] 二分类脚本成功通过增量分片拼接缓存: rows={len(merged_df):,}, dates={len(actual_dates)}"
                )
                return merged_df
            logger.warning(
                f"[MINUTE_CACHE] 二分类脚本分片缓存仍缺少 {len(missing_dates)} 个交易日: "
                f"{[d.strftime('%Y-%m-%d') for d in missing_dates[:5]]}"
            )

    if not build_if_missing:
        logger.warning("[MINUTE_CACHE] 二分类脚本未命中有效分钟缓存，当前仅尝试读取不自动构建。")
        return None

    return build_minute_trade_cache(
        target_prediction_rows=target_rows,
        context_prediction_data=context_rows,
        minute_data_path=minute_data_path,
        trading_dates=trading_dates,
        cache_path=cache_path,
        holding_days=int(holding_days),
        overwrite=False,
        log_prefix="[MINUTE_CACHE]"
    )


def _build_or_load_validation_minute_cache_binary(
    val_data_raw: Optional[pd.DataFrame],
    selection_data_raw: Optional[pd.DataFrame] = None,
    test_data_raw: Optional[pd.DataFrame] = None,
    holding_days: int = 3,
    minute_data_path: str = "../local_data/minute/",
    build_if_missing: bool = False,
    extra_dates=None,
) -> Optional[pd.DataFrame]:
    """加载V3分钟标签缓存，统一候选评估和V15使用的分钟收益口径。

    V3使用首根5分钟VWAP作为基准买价，遵守T+1不可卖出，并包含复权、
    缺失交易日和分钟数据质量审计。entry gap只作为诊断字段，不使标签失效。
    [v29] extra_dates: FOLD0压力测试验证期额外日期（3月挖洞段2025-03-08~25 +
    前向段2025-04-01~06-30），并入缓存加载范围——3月作为FOLD0验证集本该有分钟缓存，
    但val/test data不覆盖3月导致缓存漏加载（用户指出的bug）。
    """
    del holding_days, minute_data_path, build_if_missing
    if val_data_raw is None or len(val_data_raw) == 0:
        return None

    from minute_label_cache_loader import load_minute_label_cache

    context_frames = [
        df for df in (val_data_raw, selection_data_raw, test_data_raw)
        if df is not None and len(df) > 0
    ]
    all_dates = pd.concat(
        [pd.to_datetime(df["date"], errors="coerce") for df in context_frames],
        ignore_index=True,
    ).dropna()
    if extra_dates is not None and len(extra_dates) > 0:
        all_dates = pd.concat(
            [all_dates, pd.to_datetime(pd.Series(extra_dates), errors="coerce")],
            ignore_index=True,
        ).dropna()
    if all_dates.empty:
        return None

    start_ts = all_dates.min()
    end_ts = all_dates.max()
    cache_columns = [
        'date', 'stock_code', 'label_return', 'label_valid',
        'minute_realized_return', 'maturity_return', 'minute_min_return', 'minute_max_drawdown',
        'buy_executable', 'skip_reason', 'entry_gap_pct',
        'entry_gap_skip_policy', 'exit_reason', 'stoploss_hit',
        'profit_bearish_hit', 'holding_days_realized', 'missing_minute_data',
        'adj_factor_changed',
    ]
    try:
        cache_df = load_minute_label_cache(
            start_ts, end_ts, columns=cache_columns, cache_dir=MINUTE_CACHE_DIR_ADJ, logger=logger
        )
    except (FileNotFoundError, ValueError) as exc:
        logger.warning(f"[MINUTE_CACHE-V3] 加载V3分钟标签缓存失败: {exc}")
        return None

    logger.info(
        "[MINUTE_CACHE-V3] 已加载: rows=%s, dates=%s, range=%s~%s, "
        "gap_policy=diagnostic_only",
        f"{len(cache_df):,}",
        f"{cache_df['date'].nunique():,}",
        pd.to_datetime(cache_df["date"]).min().strftime("%Y-%m-%d"),
        pd.to_datetime(cache_df["date"]).max().strftime("%Y-%m-%d"),
    )
    return cache_df


def _calc_daily_rank_panel_binary(model, X_eval, y_eval_original, eval_dates, eval_data_raw=None, rank_position=1):
    if X_eval is None or len(X_eval) == 0 or y_eval_original is None or len(y_eval_original) == 0:
        return pd.DataFrame()
    try:
        best_iter = getattr(model, 'best_iteration', None)
        eval_pred = model.predict(X_eval, num_iteration=best_iter) if best_iter else model.predict(X_eval)
    except Exception:
        eval_pred = model.predict(X_eval)

    eval_pred = np.asarray(eval_pred, dtype=float).reshape(-1)
    y_eval_original = np.asarray(y_eval_original, dtype=float).reshape(-1)
    n = min(len(eval_pred), len(y_eval_original), len(eval_dates))
    if n <= 0:
        return pd.DataFrame()

    df = pd.DataFrame({
        'date': pd.to_datetime(eval_dates[:n]),
        'pred': eval_pred[:n],
        'actual_return': y_eval_original[:n]
    })
    if eval_data_raw is not None and len(eval_data_raw) > 0:
        eval_data_raw_aligned = eval_data_raw.reset_index(drop=True)
        for col in ['stock_code', 'relevance', 'future_min_low_ret', 'risk_adjusted_return_label']:
            if col in eval_data_raw_aligned.columns:
                df[col] = eval_data_raw_aligned[col].values[:len(df)]

    rows = []
    for date_val, group in df.groupby('date', sort=True):
        if len(group) < max(rank_position, 5):
            continue
        sorted_group = group.sort_values('pred', ascending=False).reset_index(drop=True)
        row = sorted_group.iloc[rank_position - 1]
        rows.append({
            'date': date_val,
            'stock_code': row.get('stock_code'),
            'rank': int(rank_position),
            'pred_score': float(row['pred']),
            'actual_return': float(row['actual_return']),
            'relevance': float(row['relevance']) if 'relevance' in row and pd.notna(row['relevance']) else np.nan,
            'future_min_low_ret': float(row['future_min_low_ret']) if 'future_min_low_ret' in row and pd.notna(row['future_min_low_ret']) else np.nan,
            'risk_adjusted_return_label': float(row['risk_adjusted_return_label']) if 'risk_adjusted_return_label' in row and pd.notna(row['risk_adjusted_return_label']) else np.nan,
        })
    return pd.DataFrame(rows)


def _calc_daily_topk_selection_rows_binary(model, X_eval, y_eval_original, eval_dates, eval_data_raw=None, top_k=3, min_group_size=5):
    try:
        best_iter = getattr(model, 'best_iteration', None)
        eval_pred = model.predict(X_eval, num_iteration=best_iter) if best_iter else model.predict(X_eval)
    except Exception:
        eval_pred = model.predict(X_eval)

    eval_pred = np.asarray(eval_pred, dtype=float).reshape(-1)
    y_eval_original = np.asarray(y_eval_original, dtype=float).reshape(-1)
    n = min(len(eval_pred), len(y_eval_original), len(eval_dates))
    if n <= 0:
        return pd.DataFrame()

    df = pd.DataFrame({
        'date': pd.to_datetime(eval_dates[:n]),
        'pred': eval_pred[:n],
        'actual_return': y_eval_original[:n]
    })
    if eval_data_raw is not None and len(eval_data_raw) > 0:
        eval_data_raw_aligned = eval_data_raw.reset_index(drop=True)
        for col in ['stock_code', 'relevance', 'future_min_low_ret', 'risk_adjusted_return_label']:
            if col in eval_data_raw_aligned.columns:
                df[col] = eval_data_raw_aligned[col].values[:len(df)]

    selected_rows = []
    for date_val, group in df.groupby('date', sort=True):
        if len(group) < max(top_k, min_group_size):
            continue
        sorted_group = group.sort_values('pred', ascending=False).reset_index(drop=True)
        basket = sorted_group.head(top_k).copy()
        for rank_idx, row in enumerate(basket.itertuples(index=False), 1):
            selected_rows.append({
                'date': date_val,
                'stock_code': getattr(row, 'stock_code', None),
                'rank': int(rank_idx),
                'pred_score': float(getattr(row, 'pred')),
                'actual_return': float(getattr(row, 'actual_return')),
                'relevance': float(getattr(row, 'relevance', np.nan)) if pd.notna(getattr(row, 'relevance', np.nan)) else np.nan,
                'future_min_low_ret': float(getattr(row, 'future_min_low_ret', np.nan)) if pd.notna(getattr(row, 'future_min_low_ret', np.nan)) else np.nan,
                'risk_adjusted_return_label': float(getattr(row, 'risk_adjusted_return_label', np.nan)) if pd.notna(getattr(row, 'risk_adjusted_return_label', np.nan)) else np.nan,
            })
    return pd.DataFrame(selected_rows)


def _classify_diag_category(panel):
    """按 成交/止损卖出/高开跳过/低开跳过/其他跳过 分类分钟面板行。"""
    cat = pd.Series("成交", index=panel.index, dtype=object)
    exec_mask = (
        panel["buy_executable"].fillna(False).astype(bool)
        if "buy_executable" in panel.columns
        else pd.Series(True, index=panel.index)
    )
    stop = pd.Series(False, index=panel.index)
    if "stoploss_hit" in panel.columns:
        stop = exec_mask & panel["stoploss_hit"].fillna(False).astype(bool)
    skip = ~exec_mask
    gap_up = pd.Series(False, index=panel.index)
    gap_dn = pd.Series(False, index=panel.index)
    if "entry_gap_pct" in panel.columns and "rank" in panel.columns:
        gap = pd.to_numeric(panel["entry_gap_pct"], errors="coerce")
        rank = pd.to_numeric(panel["rank"], errors="coerce")
        gap_up = skip & gap.notna() & (gap > MINUTE_BACKTEST_ENTRY_GAP_UP)
        gap_dn = skip & gap.notna() & (
            gap < np.where(
                rank == 1,
                MINUTE_BACKTEST_ENTRY_GAP_DOWN_TOP1,
                MINUTE_BACKTEST_ENTRY_GAP_DOWN_NON_TOP1,
            )
        )
    if "skip_reason" in panel.columns:
        reason = panel["skip_reason"].astype(str)
        gap_up = gap_up | (skip & reason.str.contains("高开", na=False))
        gap_dn = gap_dn | (skip & reason.str.contains("低开", na=False))
    other = skip & ~gap_up & ~gap_dn
    cat[stop] = "止损卖出"
    cat[gap_up] = "高开跳过"
    cat[gap_dn] = "低开跳过"
    cat[other] = "其他跳过"
    return cat


def _log_stop_skip_stats_by_rank(panel, prefix="[MINUTE-DIAG]"):
    """按 rank×类别 统计3日收益（label_return / future_return_3d），
    观察止损/跳过样本在Top1~5之间的漂移。

    panel 需含列: rank, label_return, category
    category 可用 _classify_diag_category 生成。
    [v65-perf] swap折诊断（[SWAP-FOLD]前缀）默认关闭：省每折panel分组计算与海量日志。
    """
    if "SWAP-FOLD" in str(prefix) and not CS_SWAP_FOLD_VERBOSE:
        return
    if panel is None or len(panel) == 0:
        return
    label = pd.to_numeric(panel.get("label_return"), errors="coerce")
    rank_s = pd.to_numeric(panel.get("rank"), errors="coerce")
    ranks = sorted({int(r) for r in rank_s.dropna() if r >= 1})
    cats = ["成交", "可成交", "止损卖出", "高开跳过", "低开跳过", "其他跳过"]
    for r in ranks:
        rmask = rank_s == r
        for c in cats:
            m = rmask & (panel["category"] == c)
            n = int(m.sum())
            if n == 0:
                continue
            vals = label[m].dropna()
            if vals.empty:
                logger.info(f"{prefix} rank{int(r)} {c}: n={n}（3日收益缺失）")
                continue
            logger.info(
                f"{prefix} rank{int(r)} {c}: n={n}, 3日收益 mean={vals.mean():.4f}, "
                f"median={vals.median():.4f}, 正收益占比={float((vals > 0).mean()):.1%}, "
                f"最大={vals.max():.4f}, 最小={vals.min():.4f}"
            )
            # [v43] 止损股“不止损持有到T+3”的假设检验：止损后是继续跌还是拉回
            if c == "止损卖出" and "maturity_return" in panel.columns:
                mat = pd.to_numeric(panel.loc[m, "maturity_return"], errors="coerce").dropna()
                if len(mat) > 0:
                    logger.info(
                        f"{prefix} rank{int(r)} 止损卖出(不止损持有至T+3): n={len(mat)}, "
                        f"3日收益 mean={mat.mean():.4f}, median={mat.median():.4f}, "
                        f"正收益占比={float((mat > 0).mean()):.1%}, "
                        f"<=-5%占比={float((mat <= -0.05).mean()):.1%}"
                    )


_TOP5_NULL_MEMO = {}
_NULL_MEMO_LOCK = threading.Lock()  # [SWAP-PARALLEL] swap 并行时避免同一 null 键重复计算


def _build_top5_null_series(minute_cache_df, eval_dates, n_draws=CS_NULL_DRAWS, seed=CS_NULL_SEED):
    """[v58] Phase B 零分布：每个评估日从可执行股票全集无放回抽 R 组 5 只，
    组值=5只 effective 收益均值（与模型top5篮子同语义：可执行→label_return，否则补0，含止损路径）。
    返回 (null_mean_Series, null_std_Series) 按日索引（datetime64[D] 归一化）。
    null与候选无关 → memoize（key=缓存对象id + 日期集合 + R + seed）。
    当日可执行股 <5 时该日不出现在null（模型侧同日也会因 min_group_size=5 剔除，天然对齐）。
    """
    import numpy as np
    import pandas as pd
    if minute_cache_df is None or len(minute_cache_df) == 0:
        return None, None
    cols = [c for c in ('date', 'buy_executable', 'label_valid', 'adj_factor_changed',
                        'label_return', 'minute_realized_return') if c in minute_cache_df.columns]
    key_dates = tuple(sorted(set(pd.to_datetime(pd.Series(eval_dates)).dt.normalize().dropna())))
    if not key_dates:
        return None, None
    mkey = (id(minute_cache_df), key_dates, int(n_draws), int(seed))
    with _NULL_MEMO_LOCK:
        cached = _TOP5_NULL_MEMO.get(mkey)
        if cached is not None:
            return cached
    view = minute_cache_df[cols].copy()
    view['date'] = pd.to_datetime(view['date']).dt.normalize()
    ok = (view['buy_executable'].fillna(False).astype(bool)
          & view['label_valid'].fillna(False).astype(bool)
          & ~view['adj_factor_changed'].fillna(True).astype(bool))
    ret_col = 'label_return' if 'label_return' in view.columns else 'minute_realized_return'
    view['_ret'] = pd.to_numeric(view.get(ret_col, 0.0), errors='coerce').fillna(0.0)
    ok &= view['_ret'].notna()
    view = view[ok & view['date'].isin(key_dates)]
    null_means, null_stds = {}, {}
    rng = np.random.default_rng(int(seed))
    for d, g in view.groupby('date', sort=True):
        vals = g['_ret'].to_numpy(dtype=float)
        n = int(len(vals))
        if n < 5:
            continue
        draws = np.empty(int(n_draws), dtype=float)
        for r in range(int(n_draws)):
            draws[r] = vals[rng.choice(n, size=5, replace=False)].mean()
        null_means[d] = float(draws.mean())
        s = float(draws.std(ddof=1)) if int(n_draws) > 1 else 0.0
        if s <= 0:
            s = float(vals.std(ddof=1)) if n > 1 else 0.0
        null_stds[d] = s
    if not null_means:
        with _NULL_MEMO_LOCK:
            _TOP5_NULL_MEMO[mkey] = (None, None)
        return None, None
    _nm = pd.Series(null_means).sort_index()
    _ns = pd.Series(null_stds).sort_index()
    with _NULL_MEMO_LOCK:
        if mkey in _TOP5_NULL_MEMO:
            return _TOP5_NULL_MEMO[mkey]
        _TOP5_NULL_MEMO[mkey] = (_nm, _ns)
    return _nm, _ns


def _evaluate_candidate_with_minute_cache_binary(model, X_eval, y_eval_original, eval_dates, eval_data_raw, minute_cache_df, diag_prefix="[MINUTE-DIAG] 验证集最佳候选"):
    if minute_cache_df is None or len(minute_cache_df) == 0:
        return None

    # 一次预测取每日前5名，后续同时计算Top1、Top3/Top5组合以及
    # Top1相对Rank2~5的头部排序优势，避免同一候选重复predict三次。
    top5_panel = _calc_daily_topk_selection_rows_binary(
        model, X_eval, y_eval_original, eval_dates, eval_data_raw,
        top_k=5, min_group_size=5,
    )
    if top5_panel is None or top5_panel.empty:
        return None

    cache_cols = [
        'date', 'stock_code', 'buy_executable', 'skip_reason', 'exit_reason',
        'minute_realized_return', 'maturity_return', 'minute_min_return', 'minute_max_drawdown',
        'label_return', 'entry_gap_pct', 'entry_gap_skip_policy',
        'stoploss_hit', 'profit_bearish_hit', 'holding_days_realized',
        'missing_minute_data', 'adj_factor_changed', 'label_valid'
    ]
    cache_view = minute_cache_df[[c for c in cache_cols if c in minute_cache_df.columns]].copy()
    cache_view['date'] = pd.to_datetime(cache_view['date'])

    ranked_merged = top5_panel.merge(cache_view, on=['date', 'stock_code'], how='left')
    ranked_merged['buy_executable'] = ranked_merged['buy_executable'].fillna(False).astype(bool)
    ranked_merged['missing_minute_data'] = ranked_merged['missing_minute_data'].fillna(True).astype(bool)
    ranked_merged['stoploss_hit'] = ranked_merged['stoploss_hit'].fillna(False).astype(bool)
    ranked_merged['profit_bearish_hit'] = ranked_merged['profit_bearish_hit'].fillna(False).astype(bool)

    if 'label_valid' in ranked_merged.columns:
        ranked_merged['buy_executable'] &= ranked_merged['label_valid'].fillna(False).astype(bool)
    if 'adj_factor_changed' in ranked_merged.columns:
        ranked_merged['buy_executable'] &= ~ranked_merged['adj_factor_changed'].fillna(True).astype(bool)

    # V3不因未来高低开删除标签；候选评估仍需模拟copy.py真实交易策略。
    entry_gap_source = ranked_merged.get(
        'entry_gap_pct', pd.Series(np.nan, index=ranked_merged.index)
    )
    entry_gap = pd.to_numeric(entry_gap_source, errors='coerce')
    gap_down_threshold = np.where(
        ranked_merged['rank'].eq(1),
        MINUTE_BACKTEST_ENTRY_GAP_DOWN_TOP1,
        MINUTE_BACKTEST_ENTRY_GAP_DOWN_NON_TOP1,
    )
    entry_gap_allowed = (
        entry_gap.notna()
        & entry_gap.ge(gap_down_threshold)
        & entry_gap.le(MINUTE_BACKTEST_ENTRY_GAP_UP)
    )
    ranked_merged['entry_policy_skip'] = ranked_merged['buy_executable'] & ~entry_gap_allowed
    ranked_merged['buy_executable'] &= entry_gap_allowed

    return_col = (
        'label_return' if 'label_return' in ranked_merged.columns
        else 'minute_realized_return'
    )
    ranked_merged['policy_minute_return'] = pd.to_numeric(
        ranked_merged.get(return_col, 0.0), errors='coerce'
    ).fillna(0.0)
    ranked_merged['effective_minute_return'] = np.where(
        ranked_merged['buy_executable'], ranked_merged['policy_minute_return'], 0.0
    )

    # 标签持有期为T+1~T+3。验证期最前面的3个交易日只作embargo，
    # 防止训练集末端标签路径和验证收益路径发生边界重叠。
    all_validation_days = np.array(sorted(pd.to_datetime(ranked_merged['date']).unique()))
    embargo_day_count = min(3, max(0, len(all_validation_days) - 3))
    embargo_days = all_validation_days[:embargo_day_count]
    evaluation_days = all_validation_days[embargo_day_count:]
    ranked_merged = ranked_merged[ranked_merged['date'].isin(evaluation_days)].copy()
    if ranked_merged.empty:
        return None

    top1_merged = ranked_merged[ranked_merged['rank'] == 1].copy()

    if "buy_executable" in top1_merged.columns:
        _exec_mask = top1_merged["buy_executable"].fillna(False).astype(bool)
        rets = top1_merged.loc[_exec_mask, "effective_minute_return"].values.astype(float)
    else:
        _exec_mask = pd.Series(True, index=top1_merged.index)
        rets = top1_merged["effective_minute_return"].values.astype(float)
    # [MINUTE-REAL] 所有 rank1 指标只统计真实成交（含止损退出），跳过日不计入收益。
    mean_return = float(np.mean(rets)) if len(rets) > 0 else 0.0
    median_return = float(np.median(rets)) if len(rets) > 0 else 0.0
    win_rate = float(np.mean(rets > 0)) if len(rets) > 0 else 0.0
    q10 = float(np.percentile(rets, 10)) if len(rets) > 0 else 0.0
    max_drawdown = _calc_max_drawdown(rets)
    cumulative_return = float(np.prod(1.0 + rets) - 1.0) if len(rets) > 0 else 0.0
    ret_std = float(np.std(rets)) if len(rets) > 1 else 0.0
    downside_rets = rets[rets < 0]
    downside_std = float(np.std(downside_rets)) if len(downside_rets) > 0 else 0.0
    drawdown_abs = max(abs(max_drawdown), 0.05)
    calmar_like = cumulative_return / drawdown_abs
    efficiency_gap = cumulative_return + max_drawdown
    sharpe_like = mean_return / max(ret_std, 0.01)
    sortino_like = mean_return / max(downside_std, 0.01)
    _exec_n = int(_exec_mask.sum())
    # [SWAP-REPORT] 逐日口径：跳过日按 0（空仓）计入，与 top5-null z_t 篮子一致。
    # mean_return（成交日均值）≠ 策略逐日收益，二者差一个 skip 加权；
    # 真实逐日收益 ≈ mean_return × (n_exec/n_total)。同时暴露 n_exec/n_total。
    _n_total = int(len(top1_merged))
    _perday_vals = top1_merged["effective_minute_return"].astype(float).to_numpy() if _n_total else np.zeros(0)
    mean_return_per_day = float(np.mean(_perday_vals)) if _n_total > 0 else 0.0
    win_rate_per_day = float(np.mean(_perday_vals > 0)) if _n_total > 0 else 0.0
    n_exec = _exec_n
    n_total_days = _n_total
    stoploss_rate = float(np.mean(top1_merged.loc[_exec_mask, "stoploss_hit"])) if _exec_n > 0 else 0.0
    profit_bearish_rate = float(np.mean(top1_merged.loc[_exec_mask, "profit_bearish_hit"])) if _exec_n > 0 else 0.0
    skip_rate = float(np.mean(~top1_merged["buy_executable"].fillna(False))) if len(top1_merged) > 0 else 0.0
    missing_rate = float(np.mean(top1_merged["missing_minute_data"].fillna(True))) if len(top1_merged) > 0 else 0.0
    _exec_rets_diag = rets

    # [MINUTE-DIAG] 按 rank×类别 统计止损/跳过样本的3日收益（观察Top1~5漂移）
    try:
        _diag_panel = ranked_merged[
            ["date", "stock_code", "rank", "label_return", "buy_executable",
             "stoploss_hit", "entry_gap_pct", "skip_reason", "maturity_return"]
        ].copy()
        _diag_panel["category"] = _classify_diag_category(_diag_panel)
        _log_stop_skip_stats_by_rank(_diag_panel, prefix=diag_prefix)
    except Exception as _de:
        logger.warning(f"[MINUTE-DIAG] 验证集止损/跳过按rank统计失败: {_de}")

    daily_rank_returns = (
        ranked_merged
        .pivot_table(
            index='date', columns='rank', values='effective_minute_return',
            aggfunc='first', observed=False,
        )
        .reindex(columns=[1, 2, 3, 4, 5])
        .sort_index()
    )
    peer_returns = daily_rank_returns[[2, 3, 4, 5]].mean(axis=1, skipna=False)
    head_gap = (daily_rank_returns[1] - peer_returns).dropna()
    head_gap_mean = float(head_gap.mean()) if len(head_gap) else 0.0
    head_gap_median = float(head_gap.median()) if len(head_gap) else 0.0
    head_gap_positive_ratio = float((head_gap > 0).mean()) if len(head_gap) else 0.0
    peer_mean_return = float(peer_returns.mean()) if peer_returns.notna().any() else 0.0
    # [CODEX-STEP3] winner_t：HAC-t(Top1 − median(Top2..5))（Concentration edge，Top1锋利度）
    # monotonicity：每日 rank1>=rank2>=...>=rank5 的天数占比（排序一致性）
    try:
        _w_series = (daily_rank_returns[1] - daily_rank_returns[[2, 3, 4, 5]].median(axis=1)).dropna()
        winner_t = _hac_tstat(_w_series.to_numpy(dtype=float)) if len(_w_series) >= 20 else float('nan')
    except Exception:
        winner_t = float('nan')
    try:
        _mono_rows = daily_rank_returns[[1, 2, 3, 4, 5]].dropna(how='any')
        _mono = float((np.diff(_mono_rows.to_numpy(dtype=float), axis=1) <= 0).all(axis=1).mean()) if len(_mono_rows) > 0 else float('nan')
    except Exception:
        _mono = float('nan')

    rank_return_metrics = {}
    for rank_position in range(1, 6):
        rank_rets = pd.to_numeric(daily_rank_returns[rank_position], errors='coerce').dropna().to_numpy(float)
        rank_return_metrics[str(rank_position)] = {
            'days': int(len(rank_rets)),
            'mean_return': float(np.mean(rank_rets)) if len(rank_rets) else 0.0,
            'median_return': float(np.median(rank_rets)) if len(rank_rets) else 0.0,
            'cumulative_return': (
                float(np.prod(1.0 + rank_rets) - 1.0) if len(rank_rets) else 0.0
            ),
        }
    # [v52] Top3篮子主评估：每日rank1~3等权均值 + 相对当日全市场均值的超额（剔除市场beta）
    _t3_series = daily_rank_returns[[1, 2, 3]].mean(axis=1, skipna=False).dropna()
    _t3_rets = _t3_series.to_numpy(dtype=float)
    try:
        _mk = minute_cache_df[["date", "buy_executable", "label_valid", "adj_factor_changed", "label_return"]].copy()
        _mk_ok = (_mk["buy_executable"].fillna(False).astype(bool)
                  & _mk["label_valid"].fillna(False).astype(bool)
                  & ~_mk["adj_factor_changed"].fillna(True).astype(bool))
        _mk_dates = pd.to_datetime(_mk.loc[_mk_ok, "date"])
        _mkt_mean = pd.to_numeric(_mk.loc[_mk_ok, "label_return"], errors="coerce").groupby(_mk_dates).mean()
    except Exception:
        _mkt_mean = pd.Series(dtype=float)
    _t3_ex_series = _t3_series - _mkt_mean.reindex(_t3_series.index)
    _t3_ex = _t3_ex_series.dropna()
    _t3_ex_arr = _t3_ex.to_numpy(dtype=float)
    top3_excess_t = _hac_tstat(_t3_ex_arr) if len(_t3_ex_arr) >= 20 else np.nan
    top3_excess_median = float(np.median(_t3_ex_arr)) if len(_t3_ex_arr) > 0 else np.nan
    if len(_t3_ex_arr) >= 20:
        _q05 = float(np.quantile(_t3_ex_arr, 0.05))
        top3_excess_cvar5 = float(np.mean(_t3_ex_arr[_t3_ex_arr <= _q05]))
    else:
        top3_excess_cvar5 = np.nan
    head_gap_t = _hac_tstat(head_gap.to_numpy(dtype=float)) if len(head_gap) >= 20 else np.nan
    # [v58] Phase B：top5 篮子 vs 同日随机5只零分布（相对判据，主评估）。
    # z_d = (模型top5日均 − null_mean_d) / null_std_d；null=可执行全集无放回抽R组5只。
    # 聚合：z_mean / z_t(HAC) / pos_share。top5 vs 市场均值仅作报告列。
    _t5_series = daily_rank_returns[list(range(1, 6))].mean(axis=1, skipna=False).dropna()
    _t5_series.index = pd.to_datetime(_t5_series.index).normalize()
    _t5_rets = _t5_series.to_numpy(dtype=float)
    _nm5, _ns5 = _build_top5_null_series(minute_cache_df, _t5_series.index)
    _z_series = None
    if _nm5 is not None and _ns5 is not None:
        _nm5 = _nm5.reindex(_t5_series.index)
        _ns5 = _ns5.reindex(_t5_series.index)
        _okz = _nm5.notna() & _ns5.notna() & (_ns5 > 0)
        if int(_okz.sum()) >= 20:
            _z_series = (_t5_series[_okz] - _nm5[_okz]) / _ns5[_okz]
    if _z_series is not None and len(_z_series) >= 20:
        _z_arr = _z_series.to_numpy(dtype=float)
        top5_null_z_mean = float(np.mean(_z_arr))
        top5_null_z_t = _hac_tstat(_z_arr)
        top5_null_pos_share = float(np.mean(_z_arr > 0))
        top5_null_days = int(len(_z_arr))
    else:
        top5_null_z_mean = float('nan')
        top5_null_z_t = float('nan')
        top5_null_pos_share = float('nan')
        top5_null_days = int(len(_t5_series))
    _t5_ex_series = _t5_series - _mkt_mean.reindex(_t5_series.index)
    _t5_ex_arr = _t5_ex_series.dropna().to_numpy(dtype=float)
    top5_excess_t = _hac_tstat(_t5_ex_arr) if len(_t5_ex_arr) >= 20 else float('nan')
    if len(_t3_rets) > 0:
        top3_mean_return = float(np.mean(_t3_rets))
        top3_median_return = float(np.median(_t3_rets))
        top3_win_rate = float(np.mean(_t3_rets > 0))
        _t3p = _t3_rets[_t3_rets > 0]; _t3n = _t3_rets[_t3_rets < 0]
        top3_pl_ratio = float(np.mean(_t3p) / abs(np.mean(_t3n))) if len(_t3p) > 0 and len(_t3n) > 0 else (5.0 if len(_t3p) > 0 else 0.0)
        top3_mdd = _calc_max_drawdown(_t3_rets)
        if not np.isfinite(top3_mdd):
            top3_mdd = 0.0
    else:
        top3_mean_return = top3_median_return = top3_win_rate = top3_pl_ratio = top3_mdd = 0.0

    minute_segment_metrics = []
    minute_segment_penalty = 0.0
    minute_positive_segments = 0
    minute_weak_segments = 0
    head_dominance_positive_segments = 0
    unique_days = np.array(sorted(pd.to_datetime(top1_merged['date']).unique()))
    minute_day_segments = [seg for seg in np.array_split(unique_days, 3) if len(seg) > 0]
    for seg_idx, seg_days in enumerate(minute_day_segments, 1):
        seg_df = top1_merged[top1_merged['date'].isin(seg_days)].copy()
        seg_rets = seg_df['effective_minute_return'].values.astype(float)
        if len(seg_rets) == 0:
            continue
        seg_mean = float(np.mean(seg_rets))
        seg_win = float(np.mean(seg_rets > 0))
        seg_q10 = float(np.percentile(seg_rets, 10))
        seg_dd = _calc_max_drawdown(seg_rets)
        seg_cum = float(np.prod(1.0 + seg_rets) - 1.0)
        # [v48] Top3篮子分段累计（一致性门槛用）
        _t3_seg = _t3_series.reindex(pd.to_datetime(seg_days)).dropna()
        seg_top3_cum = float(np.prod(1.0 + _t3_seg.to_numpy(dtype=float)) - 1.0) if len(_t3_seg) > 0 else np.nan
        seg_stoploss = float(np.mean(seg_df['stoploss_hit'])) if len(seg_df) > 0 else 0.0
        seg_head_gap = head_gap.reindex(pd.to_datetime(seg_days)).dropna()
        seg_head_gap_mean = float(seg_head_gap.mean()) if len(seg_head_gap) else 0.0
        seg_head_gap_median = float(seg_head_gap.median()) if len(seg_head_gap) else 0.0
        seg_head_gap_positive_ratio = (
            float((seg_head_gap > 0).mean()) if len(seg_head_gap) else 0.0
        )

        if seg_cum > 0:
            minute_positive_segments += 1
        if seg_head_gap_mean > 0:
            head_dominance_positive_segments += 1
        if seg_cum < 0 or seg_dd < -0.22 or seg_stoploss > 0.18:
            minute_weak_segments += 1

        seg_penalty = 0.0
        if seg_cum < 0:
            seg_penalty += 900.0 * abs(seg_cum)
        elif seg_cum < 0.03:
            seg_penalty += 180.0 * (0.03 - seg_cum)
        if seg_dd < -0.18:
            seg_penalty += 420.0 * abs(seg_dd + 0.18)
        if seg_q10 < -0.05:
            seg_penalty += 220.0 * abs(seg_q10 + 0.05)
        if seg_stoploss > 0.12:
            seg_penalty += 180.0 * (seg_stoploss - 0.12)
        # Top1在本折落后于Rank2~5时进行辅助惩罚；绝对Top1收益仍是主目标。
        if seg_head_gap_mean < 0:
            seg_penalty += 6000.0 * abs(seg_head_gap_mean)
        if seg_head_gap_positive_ratio < 0.40:
            seg_penalty += 240.0 * (0.40 - seg_head_gap_positive_ratio)

        minute_segment_penalty += seg_penalty
        minute_segment_metrics.append({
            'segment': int(seg_idx),
            'days': int(len(seg_rets)),
            'cumulative_return': seg_cum,
            'top3_cumulative_return': seg_top3_cum,
            'mean_return': seg_mean,
            'win_rate': seg_win,
            'q10': seg_q10,
            'max_drawdown': seg_dd,
            'stoploss_rate': seg_stoploss,
            'top1_minus_top2to5_mean': seg_head_gap_mean,
            'top1_minus_top2to5_median': seg_head_gap_median,
            'top1_beats_top2to5_ratio': seg_head_gap_positive_ratio,
            'penalty': float(seg_penalty),
        })

    topk_cum_returns = {}
    for top_k in (3, 5):
        daily_means = daily_rank_returns[list(range(1, top_k + 1))].mean(
            axis=1, skipna=False
        ).dropna()
        if daily_means.empty:
            topk_cum_returns[top_k] = 0.0
            continue
        topk_cum_returns[top_k] = float(np.prod(1.0 + daily_means.values.astype(float)) - 1.0) if len(daily_means) > 0 else 0.0

    topk_penalty = 0.0
    if topk_cum_returns[3] < 0:
        topk_penalty += 420.0 * abs(topk_cum_returns[3])
    if topk_cum_returns[5] < 0:
        topk_penalty += 260.0 * abs(topk_cum_returns[5])

    # ----------------------------------------------------------------------
    # PORTFOLIO-PROXY: 等权 Top1~5 原始收益(用 policy_minute_return，不套分钟
    # 风控的 buy_executable / gap / stoploss 过滤)。这是纯选股能力指标，
    # 用于压制"Top1 幸运 outlier + Top2~5 集体亏损"的模型被选上。
    # 原理: 风控(stoploss/gap/仓位调度)会把选股烂但风控狠的模型 cum 撑高；
    # 原始等权 Top5 收益把风控遮羞布撕掉，直接看模型挑的 5 只票平均能不能赚。
    # ----------------------------------------------------------------------
    raw_daily_rank_returns = (
        ranked_merged
        .pivot_table(
            index='date', columns='rank', values='policy_minute_return',
            aggfunc='first', observed=False,
        )
        .reindex(columns=[1, 2, 3, 4, 5])
        .sort_index()
    )
    raw_top5_daily = raw_daily_rank_returns[list(range(1, 6))].mean(
        axis=1, skipna=False
    ).dropna()
    raw_top5_cum = (
        float(np.prod(1.0 + raw_top5_daily.values.astype(float)) - 1.0)
        if len(raw_top5_daily) > 0 else 0.0
    )
    raw_top5_mean = (
        float(np.mean(raw_top5_daily.values)) if len(raw_top5_daily) > 0 else 0.0
    )
    raw_top1_daily = raw_daily_rank_returns[1].dropna()
    raw_top1_cum = (
        float(np.prod(1.0 + raw_top1_daily.values.astype(float)) - 1.0)
        if len(raw_top1_daily) > 0 else 0.0
    )

    # Top1/Top5 同向性惩罚: Top1 正但 Top5 负 = 幸运 outlier，重罚。
    # Top1 正且 Top5 正但 Top1 远超 Top5 = 可疑单一 lucky pick，轻罚。
    divergence_penalty = 0.0
    if raw_top1_cum > 0 and raw_top5_cum < 0:
        divergence_penalty = 15000.0 * abs(raw_top5_cum) + 8000.0 * raw_top1_cum
    elif raw_top1_cum > 0 and raw_top5_cum >= 0:
        _ratio_denom = max(raw_top5_cum, 0.01)
        if raw_top1_cum > 2.0 * _ratio_denom and raw_top5_cum < 0.15:
            divergence_penalty = 3000.0 * (raw_top1_cum - 2.0 * _ratio_denom)

    minute_consistency_bonus = 0.0
    if minute_positive_segments >= 2:
        minute_consistency_bonus += 220.0
    if minute_positive_segments == 3:
        minute_consistency_bonus += 180.0
    if minute_weak_segments >= 2:
        minute_segment_penalty += 260.0 * minute_weak_segments

    # 全验证期的头部排序辅助项。只有Top1系统性落后时才扣分，不要求
    # 每天都胜出，避免把高方差的单日Rank差距变成新的过拟合主目标。
    head_order_penalty = (
        12000.0 * max(0.0, -head_gap_mean) +
        6000.0 * max(0.0, -head_gap_median) +
        600.0 * max(0.0, 0.45 - head_gap_positive_ratio) +
        180.0 * max(0, 2 - head_dominance_positive_segments)
    )

    minute_score = (
        500.0 * cumulative_return +
        800.0 * calmar_like +
        600.0 * efficiency_gap +
        900.0 * sharpe_like +
        700.0 * sortino_like +
        880.0 * topk_cum_returns[3] +
        700.0 * topk_cum_returns[5] +
        # PORTFOLIO-PROXY: 原始 Top5/Top1 等权收益(不套风控)，高权重压制
        # "Top1 幸运 outlier"型模型。raw_top5 权重(6000)远高于 Top1 cum(500)，
        # 确保选模优先看 5 只票的整体选股能力而非单一 lucky pick。
        6000.0 * raw_top5_cum +
        2500.0 * raw_top1_cum +
        1800.0 * mean_return +
        2400.0 * median_return +
        3500.0 * (win_rate - 0.5) +
        2200.0 * q10 -
        180.0 * stoploss_rate -
        90.0 * profit_bearish_rate -
        180.0 * skip_rate -
        180.0 * missing_rate -
        topk_penalty -
        minute_segment_penalty +
        minute_consistency_bonus -
        head_order_penalty -
        divergence_penalty
    )
    _pos_rets = _exec_rets_diag[_exec_rets_diag > 0]
    _neg_rets = _exec_rets_diag[_exec_rets_diag < 0]
    if len(_pos_rets) > 0 and len(_neg_rets) > 0:
        rank1_pl_ratio = float(np.mean(_pos_rets) / abs(np.mean(_neg_rets)))
    elif len(_pos_rets) > 0:
        rank1_pl_ratio = 5.0
    else:
        rank1_pl_ratio = 0.0
    _exec_top1 = top1_merged[top1_merged["buy_executable"].fillna(False).astype(bool)] if "buy_executable" in top1_merged.columns else top1_merged
    if len(_exec_top1) > 0 and "minute_max_drawdown" in _exec_top1.columns:
        rank1_positive_hit_rate = float(np.mean(
            (_exec_top1["effective_minute_return"] >= BINARY_EXTREME_RETURN_THRESHOLD)
            & (_exec_top1["minute_max_drawdown"] >= BINARY_EXTREME_DRAWDOWN_THRESHOLD)
        ))
    else:
        rank1_positive_hit_rate = float("nan")
    return {
        'score': float(minute_score),
        'days': int(len(top1_merged)),
        'cumulative_return': cumulative_return,
        'calmar_like': float(calmar_like),
        'efficiency_gap': float(efficiency_gap),
        'sharpe_like': float(sharpe_like),
        'sortino_like': float(sortino_like),
        'mean_return': mean_return,
        'mean_return_per_day': mean_return_per_day,
        'win_rate_per_day': win_rate_per_day,
        'n_exec': n_exec,
        'n_total_days': n_total_days,
        'median_return': median_return,
        'win_rate': win_rate,
        'rank1_pl_ratio': float(rank1_pl_ratio),
        'rank1_positive_hit_rate': float(rank1_positive_hit_rate),
        'q10': q10,
        'max_drawdown': max_drawdown,
        'stoploss_rate': stoploss_rate,
        'profit_bearish_rate': profit_bearish_rate,
        'skip_rate': skip_rate,
        'missing_rate': missing_rate,
        'top3_cum_return': float(topk_cum_returns[3]),
        'top3_mean_return': top3_mean_return,
        'top3_median_return': top3_median_return,
        'top3_win_rate': top3_win_rate,
        'top3_pl_ratio': top3_pl_ratio,
        'top3_mdd': top3_mdd,
        'top3_excess_t': top3_excess_t,
        'top3_excess_median': top3_excess_median,
        'top3_excess_cvar5': top3_excess_cvar5,
        'head_gap_t': head_gap_t,
        'winner_t': winner_t,          # [CODEX-STEP3] HAC-t(Top1−median(Top2..5))
        'monotonicity': _mono,         # [CODEX-STEP3] 每日 rank1>=..>=rank5 占比
        'top5_cum_return': float(topk_cum_returns[5]),
        'top5_mean_return': float(np.mean(_t5_rets)) if len(_t5_rets) > 0 else 0.0,
        'top5_null_z_mean': top5_null_z_mean,
        'top5_null_z_t': top5_null_z_t,
        'top5_null_pos_share': top5_null_pos_share,
        'top5_null_days': top5_null_days,
        'top5_excess_t': top5_excess_t,
        'raw_top5_cum_return': float(raw_top5_cum),
        'raw_top1_cum_return': float(raw_top1_cum),
        'raw_top5_mean_return': float(raw_top5_mean),
        'divergence_penalty': float(divergence_penalty),
        'top2to5_mean_return': peer_mean_return,
        'top1_minus_top2to5_mean': head_gap_mean,
        'top1_minus_top2to5_median': head_gap_median,
        'top1_beats_top2to5_ratio': head_gap_positive_ratio,
        'head_dominance_positive_segments': int(head_dominance_positive_segments),
        'head_order_penalty': float(head_order_penalty),
        'rank_return_metrics': rank_return_metrics,
        'segments': minute_segment_metrics,
        'validation_folds': minute_segment_metrics,
        'validation_fold_count': int(len(minute_segment_metrics)),
        'validation_scheme': 'fixed_train_purged_three_chronological_oos_folds',
        'validation_embargo_days': int(embargo_day_count),
        'validation_embargo_dates': [str(pd.Timestamp(x).date()) for x in embargo_days],
        'positive_segments': int(minute_positive_segments),
        'weak_segments': int(minute_weak_segments),
        'segment_penalty': float(minute_segment_penalty),
        'consistency_bonus': float(minute_consistency_bonus),
    }


def calculate_top_k_return(true_returns, pred_scores, k=5):
    """
    [TARGET] 计算Top-K组合收益率

    Args:
        true_returns: 真实收益率数组
        pred_scores: 预测得分数组
        k: Top-K数量

    Returns:
        float: Top-K组合平均收益率
    """
    if len(true_returns) == 0 or len(pred_scores) == 0:
        return 0.0

    if k <= 0:
        return 0.0

    # 获取Top-K股票的索引
    top_k_indices = np.argsort(pred_scores)[-k:][::-1]  # 降序排列，取前k个

    # 计算Top-K平均收益率
    top_k_returns = true_returns[top_k_indices]
    return np.mean(top_k_returns)


def calculate_win_rate(true_returns, pred_scores, k=5):
    """
    [OK] 计算胜率（Top-K中正收益股票的比例）

    Args:
        true_returns: 真实收益率数组
        pred_scores: 预测得分数组
        k: Top-K数量

    Returns:
        float: 胜率 (0-1)
    """
    if len(true_returns) == 0 or len(pred_scores) == 0:
        return 0.0

    if k <= 0:
        return 0.0

    # 获取Top-K股票的索引
    top_k_indices = np.argsort(pred_scores)[-k:][::-1]

    # 计算正收益股票的比例
    top_k_returns = true_returns[top_k_indices]
    positive_returns = top_k_returns > 0

    return np.mean(positive_returns)


def calculate_profit_loss_ratio(true_returns, pred_scores, k=5):
    """
    ⚡ 计算标准盈亏比（总盈利/总亏损）

    Args:
        true_returns: 真实收益率数组
        pred_scores: 预测得分数组
        k: Top-K数量

    Returns:
        float: 标准盈亏比（总盈利/总亏损）
    """
    if len(true_returns) == 0 or len(pred_scores) == 0:
        return 0.0

    if k <= 0:
        return 0.0

    # 获取Top-K股票的索引
    top_k_indices = np.argsort(pred_scores)[-k:][::-1]
    top_k_returns = true_returns[top_k_indices]

    # 分离正收益和负收益
    positive_returns = top_k_returns[top_k_returns > 0]
    negative_returns = top_k_returns[top_k_returns < 0]

    if len(positive_returns) == 0:
        return 0.0  # 只有亏损，没有盈利

    if len(negative_returns) == 0:
        return float('inf')  # 只有盈利，没有亏损

    # [TARGET] 标准盈亏比：总盈利 / 总亏损
    total_profit = sum(positive_returns)
    total_loss = sum(abs(v) for v in negative_returns)

    return total_profit / total_loss if total_loss > 0 else float('inf')


def calculate_sharpe_ratio(true_returns, pred_scores, k=5, risk_free_rate=0.0):
    """
    [PROFIT] 计算夏普比率（风险调整后收益）

    Args:
        true_returns: 真实收益率数组
        pred_scores: 预测得分数组
        k: Top-K数量
        risk_free_rate: 无风险收益率（默认0）

    Returns:
        float: 夏普比率
    """
    if len(true_returns) == 0 or len(pred_scores) == 0:
        return 0.0

    if k <= 0:
        return 0.0

    # 获取Top-K股票的索引
    top_k_indices = np.argsort(pred_scores)[-k:][::-1]
    top_k_returns = true_returns[top_k_indices]

    # 计算超额收益
    excess_returns = top_k_returns - risk_free_rate

    # 计算夏普比率
    mean_excess = np.mean(excess_returns)
    std_excess = np.std(excess_returns)

    if std_excess == 0:
        return 0.0

    return mean_excess / std_excess


def calculate_max_drawdown(true_returns, pred_scores, k=5):
    """
    [DOWN] 计算最大回撤（衡量极端风险）

    Args:
        true_returns: 真实收益率数组
        pred_scores: 预测得分数组
        k: Top-K数量

    Returns:
        float: 最大回撤（正值）
    """
    if len(true_returns) == 0 or len(pred_scores) == 0:
        return 0.0

    if k <= 0:
        return 0.0

    # 获取Top-K股票的索引
    top_k_indices = np.argsort(pred_scores)[-k:][::-1]
    top_k_returns = true_returns[top_k_indices]

    # 计算累积收益曲线
    cumulative_returns = np.cumprod(1 + top_k_returns)

    # 计算最大回撤
    peak = np.maximum.accumulate(cumulative_returns)
    drawdown = (peak - cumulative_returns) / peak

    return np.max(drawdown)


def calculate_excess_return(true_returns, pred_scores, k=5, benchmark_return=0.0):
    """
    [UP] 计算超额收益（相对基准的超额表现）

    Args:
        true_returns: 真实收益率数组
        pred_scores: 预测得分数组
        k: Top-K数量
        benchmark_return: 基准收益率（默认所有股票的平均收益）

    Returns:
        float: 超额收益
    """
    top_k_return = calculate_top_k_return(true_returns, pred_scores, k)

    # 如果没有提供基准，使用所有股票的平均收益
    if benchmark_return == 0.0 and len(true_returns) > 0:
        benchmark_return = np.mean(true_returns)

    return top_k_return - benchmark_return


def evaluate_investment_performance(true_returns, pred_scores, val_dates=None, k_values=[1, 2, 3, 5], risk_free_rate=0.0):
    """
    [TARGET] 投资导向的综合评估函数 - 使用日期分组平均算法

    Args:
        true_returns: 真实收益率数组
        pred_scores: 预测得分数组
        val_dates: 验证集日期数组（用于分组计算）
        k_values: Top-K值列表，默认[1,2,3,5]
        risk_free_rate: 无风险收益率

    Returns:
        dict: 包含各种投资指标的字典
    """
    results = {}

    # 如果没有日期信息，退化为整体计算
    if val_dates is None or len(val_dates) != len(true_returns):
        # 使用整体计算作为后备方案
        for k in k_values:
            if k <= len(true_returns):
                results[f'top_{k}_return'] = calculate_top_k_return(true_returns, pred_scores, k)
                results[f'top_{k}_excess_return'] = calculate_excess_return(true_returns, pred_scores, k)
                results[f'top_{k}_win_rate'] = calculate_win_rate(true_returns, pred_scores, k)
                results[f'top_{k}_profit_loss_ratio'] = calculate_profit_loss_ratio(true_returns, pred_scores, k)
                results[f'top_{k}_sharpe_ratio'] = calculate_sharpe_ratio(true_returns, pred_scores, k, risk_free_rate)
                results[f'top_{k}_max_drawdown'] = calculate_max_drawdown(true_returns, pred_scores, k)
                results[f'top_{k}_adjusted_ndcg'] = calculate_adjusted_ndcg_at_k(true_returns, pred_scores, k)

        # 计算综合评分（确保有composite_score）
        available_ks = [k for k in k_values if f'top_{k}_return' in results]
        if available_ks:
            max_k = max(available_ks)
            primary_results = {
                'top_k_return': results.get(f'top_{max_k}_return', 0.0),
                'top_k_excess_return': results.get(f'top_{max_k}_excess_return', 0.0),
                'top_k_win_rate': results.get(f'top_{max_k}_win_rate', 0.0),
                'top_k_profit_loss_ratio': results.get(f'top_{max_k}_profit_loss_ratio', 0.0),
                'top_k_sharpe_ratio': results.get(f'top_{max_k}_sharpe_ratio', 0.0),
                'top_k_max_drawdown': results.get(f'top_{max_k}_max_drawdown', 0.0),
                'adjusted_ndcg': results.get(f'top_{max_k}_adjusted_ndcg', 0.0)
            }
            results['composite_score'] = calculate_composite_investment_score(primary_results)
        else:
            results['composite_score'] = 0.0

        return results

    # [TARGET] 使用日期分组平均算法（与现有Top-k实际收益率统计保持一致）
    import pandas as pd
    from scipy.stats import spearmanr

    # 创建DataFrame便于按日期分组
    val_df = pd.DataFrame({
        'date': val_dates,
        'pred': pred_scores,
        'return': true_returns
    })

    # 为每个Top-K初始化列表
    for k in k_values:
        results[f'top_{k}_return_list'] = []
        results[f'top_{k}_win_list'] = []
        results[f'top_{k}_profit_loss_list'] = []
        results[f'top_{k}_excess_list'] = []
        results[f'top_{k}_ndcg_list'] = []

    # 计算基准收益（整个验证集按日期分组的平均收益）
    # 这与LightGBM中"验证集平均收益率"的计算方式保持一致
    benchmark_return = val_df.groupby('date')['return'].mean().mean()

    # 按日期分组计算
    for date, group in val_df.groupby('date'):
        if len(group) < 5:  # 至少需要5只股票才有意义
            continue

        group_returns = group['return'].values
        group_preds = group['pred'].values

        # 对每个Top-K计算
        for k in k_values:
            if len(group) >= k:
                # 收益率计算
                top_k_idx = group.nlargest(k, 'pred').index
                top_k_returns = group.loc[top_k_idx, 'return'].values

                # 平均收益率
                avg_return = np.mean(top_k_returns)
                results[f'top_{k}_return_list'].append(avg_return)

                # 超额收益
                excess_return = avg_return - benchmark_return
                results[f'top_{k}_excess_list'].append(excess_return)

                # 胜率
                win_rate = np.mean(top_k_returns > 0)
                results[f'top_{k}_win_list'].append(win_rate)

                # 盈亏比
                positive_returns = top_k_returns[top_k_returns > 0]
                negative_returns = top_k_returns[top_k_returns < 0]
                if len(positive_returns) > 0 and len(negative_returns) > 0:
                    profit_loss_ratio = np.mean(positive_returns) / np.mean(np.abs(negative_returns))
                elif len(positive_returns) > 0:
                    profit_loss_ratio = float('inf')
                else:
                    profit_loss_ratio = 0.0
                results[f'top_{k}_profit_loss_list'].append(profit_loss_ratio)

                # NDCG（使用改进版本）
                ndcg_k = calculate_adjusted_ndcg_at_k(group_returns, group_preds, k)
                results[f'top_{k}_ndcg_list'].append(ndcg_k)

    # 计算最终的统计指标
    for k in k_values:
        if len(results[f'top_{k}_return_list']) > 0:
            # 主要指标：使用平均值
            results[f'top_{k}_return'] = np.mean(results[f'top_{k}_return_list'])
            results[f'top_{k}_excess_return'] = np.mean(results[f'top_{k}_excess_list'])
            results[f'top_{k}_win_rate'] = np.mean(results[f'top_{k}_win_list'])

            # 盈亏比使用中位数，避免极端值影响
            profit_loss_ratios = [r for r in results[f'top_{k}_profit_loss_list'] if r != float('inf')]
            if profit_loss_ratios:
                results[f'top_{k}_profit_loss_ratio'] = np.median(profit_loss_ratios)
            else:
                results[f'top_{k}_profit_loss_ratio'] = 0.0

            # NDCG平均值
            results[f'top_{k}_adjusted_ndcg'] = np.mean(results[f'top_{k}_ndcg_list'])

            # 风险调整指标（基于收益率列表）
            returns_list = results[f'top_{k}_return_list']
            excess_returns = [r - risk_free_rate for r in returns_list]

            if len(excess_returns) > 1:
                results[f'top_{k}_sharpe_ratio'] = np.mean(excess_returns) / np.std(excess_returns) if np.std(excess_returns) > 0 else 0.0
            else:
                results[f'top_{k}_sharpe_ratio'] = 0.0

            # 最大回撤计算（基于累积收益）
            cumulative_returns = np.cumprod(1 + np.array(returns_list))
            peak = np.maximum.accumulate(cumulative_returns)
            drawdown = (peak - cumulative_returns) / peak
            results[f'top_{k}_max_drawdown'] = np.max(drawdown)
        else:
            # 如果没有有效数据，设为0
            results[f'top_{k}_return'] = 0.0
            results[f'top_{k}_excess_return'] = 0.0
            results[f'top_{k}_win_rate'] = 0.0
            results[f'top_{k}_profit_loss_ratio'] = 0.0
            results[f'top_{k}_adjusted_ndcg'] = 0.0
            results[f'top_{k}_sharpe_ratio'] = 0.0
            results[f'top_{k}_max_drawdown'] = 0.0

    # 综合评分（主要基于最大可用的Top-K）
    # 确保即使某些Top-K无法计算，也能得到composite_score
    available_ks = [k for k in k_values if f'top_{k}_return' in results]

    if available_ks:
        # 使用最大可用的k值进行综合评分
        max_k = max(available_ks)
        primary_results = {
            'top_k_return': results.get(f'top_{max_k}_return', 0.0),
            'top_k_excess_return': results.get(f'top_{max_k}_excess_return', 0.0),
            'top_k_win_rate': results.get(f'top_{max_k}_win_rate', 0.0),
            'top_k_profit_loss_ratio': results.get(f'top_{max_k}_profit_loss_ratio', 0.0),
            'top_k_sharpe_ratio': results.get(f'top_{max_k}_sharpe_ratio', 0.0),
            'top_k_max_drawdown': results.get(f'top_{max_k}_max_drawdown', 0.0),
            'adjusted_ndcg': results.get(f'top_{max_k}_adjusted_ndcg', 0.0)
        }
        results['composite_score'] = calculate_composite_investment_score(primary_results)
    else:
        # 如果没有任何可用的Top-K数据，设置默认值
        results['composite_score'] = 0.0

    return results


def calculate_composite_investment_score(metrics):
    """
    [TROPHY] 计算综合投资评分 - 聚焦交易盈利能力

    核心理念：只关心交易能否盈利，模型是否选出了足够盈利的股票

    评分策略：
    - 盈利能力占60% (收益率 + 胜率 + 盈亏比)
    - 风险控制占20% (夏普比率 + 最大回撤)
    - 排序质量占20% (改进NDCG，确保能选出好股票)

    Args:
        metrics: 评估指标字典 (使用top_k_return, top_k_win_rate等)

    Returns:
        float: 综合评分 (0-100)
    """
    score = 0

    # 1. 盈利能力评分 (60分) - 核心关注点
    profit_score = 0

    # 收益率评分 (30分)
    if metrics['top_k_return'] > 0:
        # 正收益才能得分，收益越高分数越高
        profit_score += min(30, metrics['top_k_return'] * 200)  # 1%收益 = 2分，最高30分

    # 胜率评分 (20分) - 选对盈利股票的能力
    profit_score += metrics['top_k_win_rate'] * 20  # 100%胜率=20分

    # 盈亏比评分 (10分) - 盈利时赚多少，亏损时亏多少
    if metrics['top_k_profit_loss_ratio'] > 1:
        profit_score += min(10, metrics['top_k_profit_loss_ratio'] * 2)  # 盈亏比>1才得分
    elif metrics['top_k_profit_loss_ratio'] > 0:
        profit_score += metrics['top_k_profit_loss_ratio'] * 5  # 盈亏比<1部分得分

    score += profit_score

    # 2. 风险控制评分 (20分) - 但不能过度影响盈利
    risk_score = 0

    # 夏普比率评分 (15分)
    if metrics['top_k_sharpe_ratio'] > 0.5:  # 夏普比率>0.5才算不错
        risk_score += min(15, metrics['top_k_sharpe_ratio'] * 10)
    elif metrics['top_k_sharpe_ratio'] > 0:
        risk_score += metrics['top_k_sharpe_ratio'] * 5

    # 最大回撤扣分 (5分惩罚)
    drawdown_penalty = min(5, metrics['top_k_max_drawdown'] * 50)  # 10%回撤扣5分
    risk_score = max(0, risk_score - drawdown_penalty)

    score += risk_score

    # 3. 排序质量评分 (20分) - 确保能选到好股票
    ranking_score = metrics['adjusted_ndcg'] * 20  # NDCG接近1得高分
    score += ranking_score

    return min(100, max(0, score))  # 限制在0-100范围内


def print_investment_evaluation_report(model_name, results):
    """
    [CHART] 打印投资评估报告 - 支持Top-1,2,3,5分开评估

    Args:
        model_name: 模型名称
        results: 评估结果字典
    """
    logger.info(f"\n[CHART] {model_name}投资评估报告")
    logger.info("=" * 80)

    # Top-K分别评估
    k_values = [1, 2, 3, 5]
    for k in k_values:
        prefix = f'top_{k}'
        if f'{prefix}_return' in results:
            logger.info(f"[TARGET] Top-{k}组合评估:")
            logger.info(f"  收益率: {results[f'{prefix}_return']:.4f} ({results[f'{prefix}_return']*100:.2f}%)")
            logger.info(f"  超额收益: {results[f'{prefix}_excess_return']:.4f} ({results[f'{prefix}_excess_return']*100:.2f}%)")
            logger.info(f"  胜率: {results[f'{prefix}_win_rate']:.2%}")
            logger.info(f"  盈亏比: {results[f'{prefix}_profit_loss_ratio']:.2f}")
            logger.info(f"  夏普比率: {results[f'{prefix}_sharpe_ratio']:.4f}")
            logger.info(f"  最大回撤: {results[f'{prefix}_max_drawdown']:.4f} ({results[f'{prefix}_max_drawdown']*100:.2f}%)")
            logger.info(f"  排序质量(NDCG@{k}): {results[f'{prefix}_adjusted_ndcg']:.4f}")
            logger.info("")

    # 综合评分 (主要基于Top-5)
    logger.info("[TROPHY] 综合评估:")
    logger.info(f"  投资评分: {results['composite_score']:.1f}/100")

    # 评级
    if results['composite_score'] >= 80:
        rating = "优秀 [STAR][STAR][STAR][STAR][STAR] (强烈推荐实盘)"
        recommendation = "该模型具有很强的盈利能力，建议重点考虑实盘应用"
    elif results['composite_score'] >= 70:
        rating = "良好 [STAR][STAR][STAR][STAR] (值得实盘)"
        recommendation = "该模型具有较好的盈利能力，可以考虑实盘应用"
    elif results['composite_score'] >= 60:
        rating = "及格 [STAR][STAR][STAR] (谨慎实盘)"
        recommendation = "该模型基本盈利，建议优化后再考虑实盘"
    elif results['composite_score'] >= 50:
        rating = "需要改进 [STAR][STAR] (不建议实盘)"
        recommendation = "该模型盈利能力不足，不建议实盘应用"
    else:
        rating = "不合格 [STAR] (重新训练)"
        recommendation = "该模型无法实现盈利，需要重新设计或训练"

    logger.info(f"  综合评级: {rating}")
    logger.info(f"  投资建议: {recommendation}")
    logger.info("=" * 80)


