def _get_model_factors(
    use_original=True,
    use_zscore=True,
    use_rankpct=True,
    use_expanding=True,
    use_intra_sector_rank=True,
    use_intra_sector_zscore=True,
):
    """
    返回V12冻结的训练因子集合。

    参数保留仅为兼容旧调用接口；V12不再通过多个旧列表拼接特征，防止无意间
    把已舍弃的噪音/重复因子重新加入。风险过滤规则需要的额外字段仍由
    _get_exhaustion_filter_extra_factors()单独加载，不会被强制作为模型特征。
    """
    factors = _get_curated_model_factors_v12()
    # logger.info(
    #     f"[FEATURE-SET] version={MODEL_FACTOR_SET_VERSION}, curated_features={len(factors)}, "
    #     f"groups=" + ",".join(f"{k}:{len(v)}" for k, v in CURATED_MODEL_FACTOR_GROUPS.items())
    # )
    return list(factors)


def _get_curated_model_factors_v12():
    """返回V14.3冻结的63因子训练集，保持分组内顺序并安全去重。"""
    factors = []
    seen = set()
    for group_name, group_factors in CURATED_MODEL_FACTOR_GROUPS.items():
        for factor in group_factors:
            if factor not in seen:
                seen.add(factor)
                factors.append(factor)
    return factors

