def _log_binary_label_stats(data, name):
    """打印二分类标签正负类样本数与收益范围。"""
    import logging
    logger = logging.getLogger(__name__)
    if "binary_extreme_label" not in data.columns or "atr_return_label" not in data.columns:
        logger.warning(f"[BINARY-LABEL] {name} 缺少 binary_extreme_label/atr_return_label 列，跳过统计")
        return
    valid = data[["binary_extreme_label", "atr_return_label"]].dropna()
    pos = valid[valid["binary_extreme_label"] > 0.5]
    neg = valid[valid["binary_extreme_label"] <= 0.5]
    logger.info(
        f"[BINARY-LABEL] {name}: 正类={len(pos):,} 负类={len(neg):,} "
        f"正类收益[min/max]={pos['atr_return_label'].min():.6f}/{pos['atr_return_label'].max():.6f} "
        f"负类收益[min/max]={neg['atr_return_label'].min():.6f}/{neg['atr_return_label'].max():.6f}"
    )
    if "trap_stop_sample" in data.columns:
        _n_trap = int((data["trap_stop_sample"].fillna(0) > 0.5).sum())
        logger.info(f"[BINARY-LABEL] {name}: 陷阱样本(该支收益达标且回撤超线)={_n_trap:,}")
    # [v39] 每日正样本数量统计：观察行情好坏时正样本供给的波动（用于feval锚设计）。
    if "date" in data.columns:
        _tmp = valid.copy()
        _tmp["date"] = data.loc[valid.index, "date"]
        _tmp["is_pos"] = _tmp["binary_extreme_label"] > 0.5
        _day_cnt = _tmp.groupby("date")["is_pos"].sum()
        if len(_day_cnt) > 0:
            logger.info(
                f"[BINARY-LABEL-DAY] {name}: 交易日={len(_day_cnt)} 有正样本天数={int((_day_cnt>0).sum())} "
                f"({float((_day_cnt>0).mean())*100:.1f}%) 每日正样本[min/median/max/mean]="
                f"{int(_day_cnt.min())}/{float(_day_cnt.median()):.1f}/{int(_day_cnt.max())}/{_day_cnt.mean():.2f}"
            )
            _b0 = int((_day_cnt == 0).sum())
            _b1 = int(((_day_cnt >= 1) & (_day_cnt <= 5)).sum())
            _b2 = int(((_day_cnt >= 6) & (_day_cnt <= 10)).sum())
            _b3 = int(((_day_cnt >= 11) & (_day_cnt <= 20)).sum())
            _b4 = int((_day_cnt > 20).sum())
            logger.info(
                f"[BINARY-LABEL-DAY] {name} 每日正样本分布: 0个={_b0}天 1~5个={_b1}天 "
                f"6~10个={_b2}天 11~20个={_b3}天 >20个={_b4}天"
            )
            # [v66] 正样本峰值日：最多正样本的一天有多少个、是哪天（观察极端供给日）
            _peak_day = _day_cnt.idxmax()
            _peak_top5 = _day_cnt.sort_values(ascending=False).head(5)
            logger.info(
                f"[BINARY-LABEL-DAY] {name} 正样本峰值日: "
                f"{pd.Timestamp(_peak_day).date()} 有 {int(_day_cnt.max())} 个正样本"
                f"（占当日样本 {_day_cnt.max() / max(1, _tmp[_tmp['date'] == _peak_day].shape[0]) * 100:.1f}%）；"
                f"Top5峰值日: " + ", ".join(
                    f"{pd.Timestamp(d).date()}={int(v)}个" for d, v in _peak_top5.items()
                )
            )
def _generate_training_labels_for_all_data(stock_data):
    """
    3日收益标签（原始收益，无截断/无回撤惩罚）：future_return_3d

    信号日：T
    买入：T+1 open
    卖出：T+3 close（持有3天）
    future_return_3d = (sell_price_proxy - buy_price) / (buy_price + 1e-12)，原始收益不截断。
    min_low_return 保留 T+1~T+3 最大回撤（负值）仅供分析，不参与标签计算。
    """
    import numpy as np
    import pandas as pd
    import logging

    logger = logging.getLogger(__name__)
    logger.info("[LABEL] 开始生成3日收益标签: future_return_3d（原始收益，无截断/无回撤惩罚）")

    stock_data = stock_data.sort_values(["stock_code", "date"]).reset_index(drop=True)
    stock_data["is_st_hist"] = _get_historical_st_flag(stock_data, logger=logger).astype(bool)
    g = stock_data.groupby("stock_code", sort=False)

    # 1) 买入价（T+1 open）
    buy_price = g["open"].shift(-1)

    # 2) T+3 close（卖出价）
    close_t3 = g["close"].shift(-3)

    # 3) T+1~T+3 最低价（用于计算最大回撤）
    low_t1 = g["low"].shift(-1)
    low_t2 = g["low"].shift(-2)
    low_t3 = g["low"].shift(-3)

    # 最大涨幅（保留供分析）
    high_t2 = g["high"].shift(-2)
    high_t3 = g["high"].shift(-3)
    max_high = np.where(
        high_t2.isna() & high_t3.isna(), np.nan,
        np.maximum(high_t2.fillna(-np.inf), high_t3.fillna(-np.inf))
    )
    max_high_return = (max_high - buy_price) / (buy_price + 1e-12)


    tp = (stock_data["open"] + stock_data["high"] + stock_data["low"] + stock_data["close"]) / 4.0
    stock_data["tp"] = tp
    
    sell_t2 = g["tp"].shift(-2)
    sell_t3 = g["tp"].shift(-3)
        
    
    # 7:3 加权：极其看重 T+2 的溢价变现能力
    sell_price_proxy = 0.7 * sell_t2.fillna(sell_t2) + 0.3 * sell_t3.fillna(sell_t3)
    
    future_return_3d = (sell_price_proxy - buy_price) / (buy_price + 1e-12)

    # 4) future_return_3d
    # future_return_3d = (close_t3 - buy_price) / (buy_price + 1e-12)
    

    # 5) future_max_drawdown_3d（负值，如 -0.05 表示回撤5%）
    min_low = np.minimum(
        low_t2.fillna(np.inf),
        low_t3.fillna(np.inf)
    )
    min_low = np.where(
        low_t1.isna() & low_t2.isna() & low_t3.isna(), np.nan, min_low
    )
    future_max_drawdown_3d = (min_low - buy_price) / (buy_price + 1e-12)
    raw_future_return_3d = future_return_3d.copy()
    raw_future_max_drawdown_3d = future_max_drawdown_3d.copy()

    # [LABELROUND] Phase C 标签轮：先加载分钟回撤缓存（risk_adjusted 支需要，且 trap 需分钟口径）。
    # 提前加载，供标签构造与陷阱样本共用；失败则 risk_adjusted 降级日线回撤并注明等效性。
    _minute_dd_raw = pd.Series(np.nan, index=future_return_3d.index, dtype=float)
    _stop_arr = np.zeros(len(future_return_3d), dtype=bool)
    _minute_cov = 0.0
    _minute_loaded = False
    # [2026-10-05] 分钟缓存门控：仅 risk_adjusted 需要（且 trap 不入权，见 _build_binary_negative_weights）。
    # 默认关闭 = 走“缺失降级日线”路径，与云端现行行为逐bit一致；开回只需置 True。
    if ENABLE_MINUTE_CACHE and CS_LABEL_FAMILY == "risk_adjusted":
        try:
            from minute_label_cache_loader import load_minute_label_cache
            _cache_df = load_minute_label_cache(
                stock_data["date"].min(), stock_data["date"].max(), cache_dir=MINUTE_CACHE_DIR_ADJ, logger=logger
            )
            _keep_cols = [c for c in ["date", "stock_code", "stoploss_hit", "minute_max_drawdown"] if c in _cache_df.columns]
            _cache_df = _cache_df[_keep_cols].copy()
            _cache_df["date"] = pd.to_datetime(_cache_df["date"]).dt.normalize()
            _cache_df["stock_code"] = _cache_df["stock_code"].astype(str)
            _tmp = stock_data[["date", "stock_code"]].reset_index(drop=True).copy()
            _tmp["date"] = pd.to_datetime(_tmp["date"]).dt.normalize()
            _tmp["stock_code"] = _tmp["stock_code"].astype(str)
            _merged = _tmp.merge(_cache_df, on=["date", "stock_code"], how="left")
            _stop_arr = _merged["stoploss_hit"].fillna(False).astype(bool).to_numpy()
            _minute_dd_raw = pd.to_numeric(_merged.get("minute_max_drawdown"), errors="coerce")
            _minute_dd_raw = _minute_dd_raw.reset_index(drop=True).reindex(future_return_3d.index).astype(float)
            _ref = future_return_3d.notna()
            _minute_cov = float(_minute_dd_raw.notna()[_ref].mean()) if bool(_ref.any()) else 0.0
            _minute_loaded = True
        except Exception as _minute_e:
            logger.warning(f"[TRAP-CACHE] 分钟缓存加载失败({_minute_e})，risk_adjusted 支将降级日线回撤并注明等效性")

    # [LABELROUND] 多周期一致(3/5)需要 R5：买入 T+1 open，卖出 T+5（TP加权 0.7*T+4 + 0.3*T+5）
    sell_t4 = g["tp"].shift(-4)
    sell_t5 = g["tp"].shift(-5)
    future_return_5d = (0.7 * sell_t4 + 0.3 * sell_t5 - buy_price) / (buy_price + 1e-12)

    # [LABELROUND] 截面分位（支2/3）：当日全市场横截面未来3日收益百分位（前2% = 相对强度）
    _pct_r3 = future_return_3d.groupby(stock_data["date"]).rank(pct=True)

    # [LABELROUND] 6支标签族（预注册冻结，一次一变量=只换标签定义）：
    _family = CS_LABEL_FAMILY
    _cfg = CS_LABEL_FAMILY_CFG.get(_family, CS_LABEL_FAMILY_CFG["binary_extreme"])
    _dd_line = _cfg["dd_min"] if _cfg["dd_min"] is not None else BINARY_EXTREME_DRAWDOWN_THRESHOLD
    _r3 = future_return_3d
    _r5 = future_return_5d
    _dd = future_max_drawdown_3d
    _dd_denom = _dd.abs()
    _ratio_daily = _r3 / _dd_denom.where(_dd_denom > 0)
    # [v67] vol_scaled_25：当日截面σ（R3 的逐日标准差，NaN自动跳过）——波动率尺度化障碍的分母
    _r3_day_std = future_return_3d.groupby(stock_data["date"]).transform("std")
    if _family == "binary_extreme":
        _positive = (_r3 >= _cfg["r3_min"]) & (_dd > _dd_line)
    elif _family == "percentile_top2":
        _positive = _pct_r3 >= (1.0 - CS_LABEL_PCT)
    elif _family == "percentile_top2_dd":
        # [v66] 用户修订：前2% + DD>-5% 之外再加绝对幅度地板 R3>=5%——
        # 弱市日"矮子里拔将军"的前2%可能只涨1~2%，不构成可交易妖股；幅度+回撤+相对强度三重条件
        _positive = ((_pct_r3 >= (1.0 - CS_LABEL_PCT))
                     & (_r3 >= _cfg["r3_min"])
                     & (_dd > _dd_line))
    elif _family == "multihorizon_35":
        # [v67] 用户修订：R5 条件 = 持续性(R5>=R3) 而非绝对值(≥12%)
        # [v68] 用户修订：补路径约束 DD3日线>-5%（_dd_line 取 cfg.dd_min=-0.05），
        #        排除"持有期内深蹲后V型反转"的正类样本，与分钟执行-5%止损/T+2弱势规则对齐
        if _cfg.get("r5_vs_r3"):
            _positive = (_r3 >= _cfg["r3_min"]) & (_r5 >= _r3) & (_dd > _dd_line)
        else:
            _positive = (_r3 >= _cfg["r3_min"]) & (_r5 >= _cfg["r5_min"]) & (_dd > _dd_line)
    elif _family == "multihorizon_35_r5tol":
        # [v74] R5容差版：只把持续性门从R5>=R3放宽到R5>=R3-tol，其余与multihorizon_35一致
        _tol = float(_cfg.get("r5_vs_r3_tol", 0.03))
        _positive = (_r3 >= _cfg["r3_min"]) & (_r5 >= _r3 - _tol) & (_dd > _dd_line)
    elif _family == "vol_scaled_25":
        # [v67] 波动率尺度化障碍：R3 ≥ k×当日截面σ（σ高→障碍自动抬高→regime免疫）
        _barrier = float(_cfg["vol_k"]) * _r3_day_std
        _positive = (_r3 >= _barrier) & (_dd > _dd_line)
    elif _family == "risk_adjusted":
        if _minute_loaded and _minute_cov >= CS_LABEL_MINUTE_COV_FLOOR:
            _md = _minute_dd_raw.abs()
            _ratio_min = _r3 / _md.where(_md > 0)
            _positive = (_r3 >= _cfg["r3_min"]) & (_ratio_min >= CS_LABEL_RISK_RATIO)
        else:
            # 降级日线回撤（预注册：注明等效性，不静默缩水）
            _positive = (_r3 >= _cfg["r3_min"]) & (_ratio_daily >= CS_LABEL_RISK_RATIO)
            logger.warning(
                f"[LABELROUND] risk_adjusted: 分钟回撤覆盖={_minute_cov:.1%}<{CS_LABEL_MINUTE_COV_FLOOR:.0%}，"
                f"降级日线回撤口径（等效性已注明，见设计文档§3.2支5）"
            )
    elif _family == "binary_extreme_relaxed":
        _positive = (_r3 >= _cfg["r3_min"]) & (_dd > _dd_line)
    else:
        _positive = (_r3 >= BINARY_EXTREME_RETURN_THRESHOLD) & (_dd > BINARY_EXTREME_DRAWDOWN_THRESHOLD)
    binary_extreme_label = _positive.astype(np.float32)
    logger.info(
        f"[LABELROUND] 标签族={_family} 配置={_cfg} 分钟回撤覆盖={_minute_cov:.1%} "
        f"正类={int(binary_extreme_label.fillna(0).sum()):,}"
    )
    # [v67-DIAG] vol_scaled 障碍分布：逐日阈值随波动率的自适应情况
    if _family == "vol_scaled_25":
        try:
            _bar_valid = _barrier.dropna()
            if len(_bar_valid):
                logger.info(
                    f"[VOL-SCALED-DIAG] 逐日障碍(k×σ截面): "
                    f"[min/P25/P50/P75/max]={_bar_valid.min():.2%}/"
                    f"{np.percentile(_bar_valid, 25):.2%}/{np.median(_bar_valid):.2%}/"
                    f"{np.percentile(_bar_valid, 75):.2%}/{_bar_valid.max():.2%} "
                    f"| 与固定8%对比: 高于8%的天数占比={( _bar_valid >= 0.08).mean():.1%}"
                )
        except Exception as _vs_e:
            logger.warning(f"[VOL-SCALED-DIAG] 统计失败: {_vs_e}")
    # [v67-COMPARE] multihorizon 新旧 R5 条件分歧诊断：两版各自选了谁、谁被翻转、翻转样本收益画像
    if _family == "multihorizon_35":
        try:
            _base_ok = (_r3 >= 0.08) & _r5.notna()
            _old_pos = _base_ok & (_r5 >= 0.12)
            _new_pos = _base_ok & (_r5 >= _r3)
            _both = int((_old_pos & _new_pos).sum())
            _new_only = int((_new_pos & ~_old_pos).sum())
            _old_only = int((_old_pos & ~_new_pos).sum())
            _neither = int((_base_ok & ~_old_pos & ~_new_pos).sum())
            logger.info(
                f"[LABELROUND-COMPARE] R5条件分歧(R3>=8%内): 两版均正={_both:,} "
                f"| 仅新版(持续性,R3<=R5<12%)={_new_only:,} "
                f"| 仅旧版(绝对,12%<=R5<R3)={_old_only:,} | 两版均负={_neither:,}"
            )
            for _tag, _mask in (("新版", _new_pos), ("旧版", _old_pos)):
                if _mask.any():
                    logger.info(
                        f"[LABELROUND-COMPARE] {_tag}正类画像: n={int(_mask.sum()):,} "
                        f"R3[P25/P50/P75]={np.percentile(_r3[_mask], 25):.1%}/"
                        f"{np.percentile(_r3[_mask], 50):.1%}/{np.percentile(_r3[_mask], 75):.1%} "
                        f"R5中位={_r5[_mask].median():.1%} "
                        f"(R5-R3)中位={(_r5 - _r3)[_mask].median():+.1%}"
                    )
        except Exception as _cmp_e:
            logger.warning(f"[LABELROUND-COMPARE] 统计失败: {_cmp_e}")
    # [RAW-3D] 标签与评估统一使用原始 future_return_3d，不再做 REGRESSION_LABEL_CAP / -0.3 clip / 回撤惩罚。

    # 5.5) 跨除权日过滤：T~T+3 期间任一天 adj_factor_changed=True -> 标签 NaN
    _adj_invalid = pd.Series(False, index=stock_data.index)
    if "adj_factor_changed" in stock_data.columns:
        _adj_t0 = stock_data["adj_factor_changed"].fillna(False).astype(bool)
        _adj_t1 = g["adj_factor_changed"].shift(-1).fillna(False).astype(bool)
        _adj_t2 = g["adj_factor_changed"].shift(-2).fillna(False).astype(bool)
        _adj_t3 = g["adj_factor_changed"].shift(-3).fillna(False).astype(bool)
        _adj_invalid = _adj_t0 | _adj_t1 | _adj_t2 | _adj_t3
        _adj_count = int(_adj_invalid.sum())
        if _adj_count > 0:
            logger.info("[LABEL] 跨除权日过滤: %s 个样本 T~T+3 期间 adj_factor_changed=True", f"{_adj_count:,}")
    if _adj_invalid.any():
        future_return_3d = future_return_3d.where(~_adj_invalid)
        future_max_drawdown_3d = future_max_drawdown_3d.where(~_adj_invalid)
        raw_future_return_3d = raw_future_return_3d.where(~_adj_invalid)
        raw_future_max_drawdown_3d = raw_future_max_drawdown_3d.where(~_adj_invalid)
        binary_extreme_label = binary_extreme_label.where(~_adj_invalid)
    # [LABELROUND] 陷阱样本（随各支阈值平移）：trap = 该支日线口径正类条件 & 回撤超线。
    # 分钟口径：trap = 该支正类条件 & (stoploss_hit 或 minute_max_drawdown<=线)。
    # 注：no_ladder 权重基线中 trap 不参与权重（仅列/统计），平移保持"正类减陷阱"语义一致。
    trap_stop_sample = (
        _positive & (future_max_drawdown_3d <= _dd_line)
    ).astype(np.float32)
    trap_stop_sample = trap_stop_sample.where(
        future_return_3d.notna() & future_max_drawdown_3d.notna()
    )
    if _minute_loaded:
        _ret_ok_arr = _positive.to_numpy(dtype=bool)
        _dd_arr = _minute_dd_raw.le(_dd_line).fillna(False).to_numpy()
        _min_trap = pd.Series(
            (_ret_ok_arr & (_stop_arr | _dd_arr)).astype(np.float32),
            index=future_return_3d.index,
        )
        _min_trap = _min_trap.where(future_return_3d.notna())
        _n_cache_trap = int(np.sum(_min_trap.fillna(0) > 0.5))
        if _n_cache_trap > 0:
            trap_stop_sample = _min_trap
            logger.info(f"[TRAP-CACHE] 分钟口径陷阱样本={_n_cache_trap:,}（替代日线口径）")
        else:
            logger.warning("[TRAP-CACHE] 分钟口径陷阱样本为0，沿用日线口径")
    if _adj_invalid.any():
        trap_stop_sample = trap_stop_sample.where(~_adj_invalid)

    # 6) 标签 = future_return_3d（纯3日收益，无风险调整）
    # 买入 T+1 open，卖出 T+3 close，收益 = (close_t3 - open_t1) / open_t1
    # 标签分布：mean≈0, std≈0.05，因子 IC=0.021（future_return_3d 测试报告）
    # [v10] 统一float32（因子已是float32，标签/收益对齐，整条链路无float64）
    risk_adjusted_label = future_return_3d.astype(np.float32)

    # 7) 赋值（已移除二分类 relevance/is_monster 残余代码）
    stock_data["atr_return_label"] = risk_adjusted_label
    stock_data["relevance"] = binary_extreme_label  # [BINARY-EXTREME] 0/1训练标签
    stock_data["binary_extreme_label"] = binary_extreme_label  # [BINARY-EXTREME] 显式列，供训练链路直接使用
    stock_data["trap_stop_sample"] = trap_stop_sample.astype(np.float32)  # [v42] 陷阱样本标记
    stock_data["future_ret"] = raw_future_return_3d.astype(np.float32)  # 原始3日收益，用于评估
    stock_data["raw_future_return_3d"] = raw_future_return_3d.astype(np.float32)
    stock_data["raw_future_max_drawdown_3d"] = raw_future_max_drawdown_3d.astype(np.float32)
    stock_data["max_high_return"] = max_high_return
    stock_data["min_low_return"] = future_max_drawdown_3d

    # 9) 历史ST窗口屏蔽
    st_t1 = g["is_st_hist"].shift(-1).fillna(False).astype(bool)
    st_t2 = g["is_st_hist"].shift(-2).fillna(False).astype(bool)
    st_t3 = g["is_st_hist"].shift(-3).fillna(False).astype(bool)
    mask_st_window = stock_data["is_st_hist"] | st_t1 | st_t2 | st_t3
    st_window_count = int(mask_st_window.sum())
    if st_window_count > 0:
        logger.info(
            f"[LABEL] ST窗口屏蔽样本: {st_window_count:,}/{len(stock_data):,} "
            f"({st_window_count / max(len(stock_data), 1):.2%})"
        )
        stock_data.loc[
            mask_st_window,
            ["atr_return_label", "future_ret", "max_high_return", "min_low_return", "relevance", "binary_extreme_label", "trap_stop_sample", "raw_future_return_3d", "raw_future_max_drawdown_3d"]
        ] = np.nan

    # 10) 过滤实盘不可交易的样本
    _valid_cs_mask = stock_data.get("valid_cs_mask", True)
    if isinstance(_valid_cs_mask, pd.Series):
        valid_cs_mask = _valid_cs_mask.reindex(stock_data.index).fillna(False).astype(bool)
    else:
        valid_cs_mask = pd.Series(_valid_cs_mask, index=stock_data.index).astype(bool)

    amount = stock_data.get("amount", 0)
    amount_val = amount.fillna(0) if hasattr(amount, "fillna") else amount

    mask_untradable = (
        (stock_data.get("is_limit_up", 0) == 1)
        | (stock_data.get("is_limit_down", 0) == 1)
        | (stock_data.get("is_can_buy", 1) == 0)
        | (stock_data.get("is_zhaban", 0) == 1)
        | (amount_val < 10_000_000)
        | (~valid_cs_mask)
    )

    stock_data.loc[mask_untradable, "atr_return_label"] = np.nan
    stock_data.loc[mask_untradable, "future_ret"] = np.nan
    # [FIX 2026-09-07] 不可交易掩码同步覆盖二分类目标列：此前仅NaN连续标签，
    # binary_extreme_label(训练用)与relevance原样保留，导致tr_ok吃进幻影标签
    #（如停牌前夜信号的跨停牌fallback收益、T+1一字板phantom positive）
    stock_data.loc[mask_untradable, "binary_extreme_label"] = np.nan
    if "relevance" in stock_data.columns:
        stock_data.loc[mask_untradable, "relevance"] = np.nan

    # 11) 统计
    valid_labels = stock_data["atr_return_label"].dropna()
    logger.info(
        "[LABEL] 3日收益标签: rows=%s, valid=%s",
        f"{len(stock_data):,}",
        f"{len(valid_labels):,}",
    )
    if len(valid_labels) > 0:
        logger.info(
            "[LABEL] return stats: mean=%.4f, std=%.4f, min=%.4f, max=%.4f",
            valid_labels.mean(), valid_labels.std(), valid_labels.min(), valid_labels.max(),
        )
        # DEBUG: 打印 label 绝对值最大的 10 个样本
        _abs_label = stock_data["atr_return_label"].abs()
        _top_idx = _abs_label.nlargest(10).index
        for _i in _top_idx:
            _r = stock_data.loc[_i]
            logger.info(
                "[LABEL-DEBUG] %s %s label=%.4f ret3d=%.4f dd=%.4f pct_chg=%.2f%%",
                _r.get("stock_code", "?"),
                _r.get("date", "?"),
                _r["atr_return_label"],
                _r.get("future_ret", float("nan")),
                _r.get("min_low_return", float("nan")),
                _r.get("pct_chg", float("nan")),
            )
        valid_dd = stock_data["min_low_return"].dropna()
        if len(valid_dd) > 0:
            logger.info(
                "[LABEL] drawdown stats: mean=%.4f, std=%.4f, min=%.4f, p5=%.4f",
                valid_dd.mean(), valid_dd.std(), valid_dd.min(), valid_dd.quantile(0.05),
            )

    return stock_data

def _extract_and_validate_labels(labeled_data, label_column='atr_return_label'):
    """
    [强化] 提取和验证连续收益标签（排序模型模式）

    Args:
        labeled_data: 包含标签的数据DataFrame
        label_column: 标签列名，固定为'atr_return_label'（连续收益标签）

    Returns:
        tuple: (labels, valid_mask, relevance, relevance_30) 或 (None, None, None, None) 如果失败
    """
    try:
        import numpy as np
        logger = logging.getLogger(__name__)

        logger.info(f"🏷️ 提取和验证连续收益标签（成本感知回归模式）...")

        # 检查标签列是否存在
        if label_column not in labeled_data.columns:
            logger.error(f"数据中缺少标签列: {label_column}")
            return None, None

        # 提取标签
        labels = labeled_data[label_column].copy()

        # 验证标签值的有效性（连续值）
        valid_labels = labels.dropna()

        logger.info(f"连续收益标签统计信息:")
        logger.info(f"  标签列: {label_column}")
        logger.info(f"  总样本数: {len(labels):,}")
        logger.info(f"  有效标签数: {len(valid_labels):,}")
        logger.info(f"  缺失标签数: {labels.isna().sum():,}")

        if len(valid_labels) > 0:
            logger.info(f"  标签范围: [{valid_labels.min():.3f}, {valid_labels.max():.3f}] ATR")
            logger.info(f"  标签均值: {valid_labels.mean():.3f} ATR")
            logger.info(f"  标签标准差: {valid_labels.std():.3f} ATR")

            # 分析收益分布
            profit_samples = (valid_labels >= ATR_MULTIPLIER_PROFIT).sum()  # 盈利样本
            loss_samples = (valid_labels <= -ATR_MULTIPLIER_LOSS).sum()   # 亏损样本
            neutral_samples = ((valid_labels > -ATR_MULTIPLIER_LOSS) & (valid_labels < ATR_MULTIPLIER_PROFIT)).sum()  # 中性样本

            logger.info(f"连续收益标签分布:")
            logger.info(f"  盈利样本 (>={ATR_MULTIPLIER_PROFIT} ATR): {profit_samples:,}个 ({profit_samples/len(valid_labels)*100:.1f}%)")
            logger.info(f"  中性样本 (-{ATR_MULTIPLIER_LOSS}~{ATR_MULTIPLIER_PROFIT} ATR): {neutral_samples:,}个 ({neutral_samples/len(valid_labels)*100:.1f}%)")
            logger.info(f"  亏损样本 (<=-{ATR_MULTIPLIER_LOSS} ATR): {loss_samples:,}个 ({loss_samples/len(valid_labels)*100:.1f}%)")

        # 创建有效样本掩码（过滤掉NaN值）
        valid_mask = labels.notna()

        # 提取relevance字段(4层)
        if 'relevance' in labeled_data.columns:
            relevance = labeled_data['relevance'].copy()
            logger.info(f"[OK] 提取relevance字段(4层): {len(relevance):,}个样本")
            relevance_dist = relevance.value_counts().sort_index().to_dict()
            logger.info(f"  Relevance分布: {relevance_dist}")
        else:
            logger.warning("[WARNING] 数据中缺少relevance字段,将使用默认值0")
            import pandas as pd
            relevance = pd.Series(0, index=labeled_data.index)

        # 🆕 提取relevance_30字段(30层)
        if 'relevance_30' in labeled_data.columns:
            relevance_30 = labeled_data['relevance_30'].copy()
            logger.info(f"[OK] 提取relevance_30字段(30层): {len(relevance_30):,}个样本")
            relevance_30_dist = relevance_30.value_counts().sort_index(ascending=False).head(5).to_dict()
            logger.info(f"  Relevance_30 Top-5分布: {relevance_30_dist}")
        else:
            logger.warning("[WARNING] 数据中缺少relevance_30字段,将使用默认值0")
            import pandas as pd
            relevance_30 = pd.Series(0, index=labeled_data.index)

        logger.info("[OK] 连续收益标签提取和验证完成")
        return labels, valid_mask, relevance, relevance_30

    except Exception as e:
        logger = logging.getLogger(__name__)
        logger.error(f"连续收益标签提取和验证失败: {e}")
        import traceback
        logger.error(f"详细错误: {traceback.format_exc()}")
        return None, None, None


def _validate_data_order(dates, labels, relevance, data_name="数据"):
    """
    [WRENCH] 验证数据顺序是否正确（按日期升序排列）

    Args:
        dates: 日期数组
        labels: 标签数组
        relevance: relevance数组
        data_name: 数据名称（用于日志）

    Returns:
        bool: True表示顺序正确，False表示顺序混乱
    """
    import numpy as np
    import pandas as pd
    logger = logging.getLogger(__name__)

    try:
        logger.info(f"[SEARCH] 验证{data_name}顺序...")

        # 检查长度一致性
        if len(dates) != len(labels) or len(dates) != len(relevance):
            logger.error(f"[FAIL] {data_name}长度不一致!")
            logger.error(f"   dates长度: {len(dates)}")
            logger.error(f"   labels长度: {len(labels)}")
            logger.error(f"   relevance长度: {len(relevance)}")
            return False

        # 检查日期是否升序排列
        dates_sorted = np.sort(dates)
        if not np.array_equal(dates, dates_sorted):
            logger.error(f"[FAIL] {data_name}日期未按升序排列!")
            # 找出第一个乱序的位置
            for i in range(1, len(dates)):
                if dates[i] < dates[i-1]:
                    logger.error(f"   第{i}个日期({dates[i]})小于第{i-1}个日期({dates[i-1]})")
                    break
            return False

        # 检查是否有NaN值
        if np.any(pd.isna(labels)):
            nan_count = pd.isna(labels).sum()
            logger.error(f"[FAIL] {data_name}标签中有{nan_count}个NaN值!")
            return False

        if np.any(pd.isna(relevance)):
            nan_count = pd.isna(relevance).sum()
            logger.error(f"[FAIL] {data_name}relevance中有{nan_count}个NaN值!")
            return False

        logger.info(f"[OK] {data_name}顺序验证通过")
        logger.info(f"   样本数: {len(dates):,}")
        logger.info(f"   日期范围: {dates[0]} ~ {dates[-1]}")
        logger.info(f"   标签范围: [{np.min(labels):.3f}, {np.max(labels):.3f}]")
        logger.info(f"   relevance范围: [{np.min(relevance):.0f}, {np.max(relevance):.0f}]")

        return True

    except Exception as e:
        logger.error(f"[FAIL] {data_name}顺序验证失败: {e}")
        import traceback
        logger.error(traceback.format_exc())
        return False


def _prepare_feature_data(input_data, feature_columns, data_type="特征数据"):
    """
    准备特征数据（因子已在生成阶段完成清洗、winsorize、归一化）

    注意：因子在生成阶段（factor_lab）已经完成了：
         1. 替换 Inf 为 NaN
         2. 每日 cross-sectional winsorize
         3. 每日截面中位数填充缺失值
         4. 每日 cross-sectional 归一化（z-score/rankpct）

         此处只做基本的数据加载和格式转换

    Args:
        input_data: 输入数据DataFrame
        feature_columns: 特征列名列表
        data_type: 数据类型描述（用于日志）

    Returns:
        tuple: (X_processed, available_features) 或 (None, None) 如果失败
    """
    try:
        import numpy as np
        logger = logging.getLogger(__name__)

        logger.info(f"[强化] 开始准备{data_type}...")

        # [CLIPBOARD] 步骤1：过滤有效的特征列
        available_features = [col for col in feature_columns if col in input_data.columns]
        missing_features = [col for col in feature_columns if col not in input_data.columns]

        if missing_features:
            logger.warning(f"缺失特征: {len(missing_features)}个")
            logger.debug(f"缺失特征列表: {missing_features[:10]}...")  # 只显示前10个

        if not available_features:
            logger.error("没有可用的特征列")
            return None, None

        logger.info(f"可用特征: {len(available_features)}个")

        # [CHART] 步骤2：提取特征数据
        feature_data = input_data[available_features].copy()

        if ENABLE_WALKFORWARD_DAILY_MEDIAN_NEUTRALIZE:
            neutralize_features = [
                col for col in WALKFORWARD_DAILY_MEDIAN_NEUTRALIZE_FACTORS
                if col in feature_data.columns
            ]
            if neutralize_features and 'date' in input_data.columns:
                group_key = input_data['date']
                for col in neutralize_features:
                    numeric_col = pd.to_numeric(input_data[col], errors='coerce')
                    feature_data[col] = numeric_col.groupby(group_key).transform('median')
                logger.info(
                    f"[中位数替换] {data_type}: 已将 {len(neutralize_features)} 个日内形态因子替换为当日横截面中位数: "
                    f"{', '.join(neutralize_features)}"
                )
            elif neutralize_features:
                logger.warning(f"[中位数替换] {data_type}: 缺少date列，无法执行当日横截面中位数替换")
            else:
                logger.info(f"[中位数替换] {data_type}: 当前特征列表未包含待替换日内形态因子")

        logger.info(f"{data_type}统计:")
        logger.info(f"  样本数: {len(feature_data):,}个")
        logger.info(f"  特征数: {len(available_features)}个")

        # [CHART] 步骤3：转换为numpy数组
        X_processed = feature_data.values.astype(np.float32)

        # [CHART] 步骤4：统计信息
        logger.info(f"[OK] {data_type}准备完成:")
        logger.info(f"  样本数: {len(X_processed):,}")
        logger.info(f"  特征数: {X_processed.shape[1]}")
        logger.info(f"  特征数据类型: {X_processed.dtype}")

        return X_processed, available_features

    except Exception as e:
        logger = logging.getLogger(__name__)
        logger.error(f"准备{data_type}失败: {e}")
        import traceback
        logger.error(f"详细错误: {traceback.format_exc()}")
        return None, None



def _save_model_results(model_results, feature_names, pca_models=None, model_type='xgboost', timestamp=None):
    """保存模型和结果（支持XGBoost和LightGBM）

    Args:
        model_results: 模型训练结果
        feature_names: 特征名称列表
        pca_models: PCA模型字典（可选，仅XGBoost使用）
        model_type: 模型类型 ('xgboost' 或 'lightgbm')
        timestamp: 统一时间戳（可选，如果为None则自动生成）
    """
    try:
        import pickle
        import json
        from datetime import datetime
        from pathlib import Path

        logger = logging.getLogger(__name__)

        # 创建结果目录
        results_dir = Path("results")
        results_dir.mkdir(exist_ok=True)

        # [强化] 使用传入的时间戳或生成新的时间戳
        if timestamp is None:
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")

        # [强化] 根据模型类型确定文件名
        model_file = results_dir / f"{model_type}_model_{timestamp}.pkl"

        # [强化] 保存模型（XGBoost和LightGBM使用不同的数据结构）
        if model_type == 'xgboost':
            with open(model_file, 'wb') as f:
                pickle.dump({
                    'model': model_results['model'],
                    'scaler': model_results['scaler'],
                    'winsorization_thresholds': {},  # 因子已在生成阶段完成winsorize
                    'pca_info': model_results['pca_info'],
                    'feature_names': feature_names,
                    'pca_models': pca_models if pca_models else {},
                    'label_stats': model_results.get('label_stats', None),
                    'interaction_info': None,
                    'model_type': 'xgboost',
                    'performance': model_results.get('performance', {}),  # [强化] 保存性能信息
                }, f)
        elif model_type == 'lightgbm':
            with open(model_file, 'wb') as f:
                pickle.dump({
                    'model': model_results['model'],
                    'scaler': model_results['scaler'],
                    'feature_names': feature_names,
                    'label_stats': model_results.get('label_stats', None),
                     'model_type': 'lightgbm',
                     'performance': model_results.get('performance', {}),  # [强化] 保存性能信息
                     'training_info': model_results.get('training_info', {}),
                     'best_params': model_results.get('model_params', {}),
                     'final_lgb_params': model_results.get('final_lgb_params', {}),
                     'large_loss_weighting': model_results.get('large_loss_weighting'),
                     'selection_large_loss_weighting': model_results.get('selection_large_loss_weighting'),
                     'industry_mapping': model_results.get('industry_mapping', None),  # [SW行业编码] 保存行业映射信息
                }, f)

        logger.info(f"[OK] {model_type.upper()}模型已保存: {model_file}")

        # 记录PCA信息
        if pca_models:
            logger.info(f"[CHART] PCA模型信息:")
            for group_name, pca_info in pca_models.items():
                if pca_info.get('applied', False):
                    original_factors = pca_info.get('original_factors', [])
                    n_components = pca_info.get('n_components', 0)
                    variance_explained = pca_info.get('variance_explained', 0)
                    logger.info(f"   {group_name}: {len(original_factors)}个特征 -> {n_components}个主成分")
                    logger.info(f"   解释方差比例: {variance_explained:.4f}")
                else:
                    logger.info(f"   {group_name}: PCA未应用")

        # 保存训练结果报告
        # [强化] 修复：安全处理feature_importance，支持DataFrame和dict格式
        feature_importance_data = None
        if model_results.get('feature_importance') is not None:
            try:
                # 尝试DataFrame格式
                feature_importance_data = model_results['feature_importance'].to_dict('records')
            except AttributeError:
                # 如果是dict格式(LightGBM),转换为list of dict
                if isinstance(model_results['feature_importance'], dict):
                    feature_importance_data = [
                        {'feature': k, 'importance': v}
                        for k, v in model_results['feature_importance'].items()
                    ]
                    logger.info("[OK] feature_importance已从dict格式转换为list格式")
                else:
                    logger.warning("feature_importance格式未知，跳过保存")
                    feature_importance_data = None

        report_data = {
            'timestamp': timestamp,
            'model_type': model_type,  # [强化] 记录模型类型
            'performance': model_results['performance'],
            'training_info': model_results['training_info'],
            'model_params': model_results['model_params'],
            'feature_importance': feature_importance_data,
        }

        # [强化] XGBoost特有的信息
        if model_type == 'xgboost':
            report_data['pca_info'] = {k: v for k, v in model_results['pca_info'].items() if k != 'pca_object'}
            report_data['interaction_info'] = model_results.get('interaction_info')

        # [强化] 根据模型类型确定文件名
        report_file = results_dir / f"training_report_{model_type}_{timestamp}.json"
        with open(report_file, 'w', encoding='utf-8') as f:
            json.dump(report_data, f, indent=2, ensure_ascii=False, default=str)
        logger.info(f"训练报告已保存: {report_file}")

        # 保存特征重要性图表（如果可能）
        try:
            import matplotlib.pyplot as plt
            import pandas as pd

            # [强化] 处理不同格式的feature_importance
            feature_importance = model_results.get('feature_importance')
            if feature_importance is not None:
                # 转换为DataFrame格式
                if isinstance(feature_importance, dict):
                    # dict格式(LightGBM)
                    importance_df = pd.DataFrame([
                        {'feature': k, 'importance': v}
                        for k, v in feature_importance.items()
                    ])
                    importance_df = importance_df.sort_values('importance', ascending=False)
                else:
                    # DataFrame格式(XGBoost)
                    importance_df = feature_importance

                # 绘制Top 20
                top_features = importance_df.head(20)

                plt.figure(figsize=(12, 8))
                plt.barh(range(len(top_features)), top_features['importance'])
                plt.yticks(range(len(top_features)), top_features['feature'])
                plt.xlabel('Feature Importance')
                plt.title(f'Top 20 Feature Importance ({model_type.upper()})')
                plt.tight_layout()

                # [强化] 根据模型类型确定文件名
                plot_file = results_dir / f"feature_importance_{model_type}_{timestamp}.png"
                plt.savefig(plot_file, dpi=300, bbox_inches='tight')
                plt.close()
                logger.info(f"特征重要性图表已保存: {plot_file}")
            else:
                logger.warning("feature_importance为None，跳过图表保存")

        except Exception as plot_e:
            logger.warning(f"保存特征重要性图表失败: {plot_e}")

        logger.info("模型结果保存完成")

    except Exception as e:
        logger = logging.getLogger(__name__)
        logger.error(f"保存模型结果失败: {e}")
        import traceback
        logger.error(f"详细错误: {traceback.format_exc()}")


