def _generate_interaction_analysis_report(interaction_names, factor_test_results,
                                        high_corr_pairs, high_vif_features,
                                        stock_features, market_features, logger,
                                        final_ranked_features=None, filtering_results=None):
    """生成交互特征分析报告"""
    try:
        logger.info("=" * 80)
        logger.info("[CLIPBOARD] 交互特征分析报告")
        logger.info("=" * 80)

        # 1. 基本统计
        logger.info("[CHART] 基本统计:")
        logger.info(f"  - 股票特征数量: {len(stock_features)}")
        logger.info(f"  - 市场特征数量: {len(market_features)}")
        logger.info(f"  - 生成交互特征数量: {len(interaction_names)}")
        logger.info(f"  - 高相关性特征对: {len(high_corr_pairs)}")
        logger.info(f"  - 高VIF特征数量: {len(high_vif_features)}")

        # 2. 单因子测试结果排序
        logger.info("\n[UP] 单因子测试结果 (按|IC|排序):")

        # 按IC绝对值排序
        sorted_results = sorted(
            factor_test_results.items(),
            key=lambda x: abs(x[1]['ic']) if not np.isnan(x[1]['ic']) else 0,
            reverse=True
        )

        logger.info("  排名  特征名称                                          IC      多空收益   样本数")
        logger.info("  " + "-" * 75)

        effective_features = []
        zero_importance_features = []

        for i, (feature_name, result) in enumerate(sorted_results, 1):
            ic = result['ic']
            ls_return = result['long_short_return']
            samples = result['valid_samples']

            if abs(ic) > 0.01:  # 认为有效的阈值
                effective_features.append(feature_name)
                status = "[OK]"
            else:
                zero_importance_features.append(feature_name)
                status = "[FAIL]"

            logger.info(f"  {i:2d}    {feature_name:<45} {ic:7.4f}  {ls_return:8.4f}  {samples:6d} {status}")

        # 3. 问题特征识别
        logger.info(f"\n[WARNING] 问题特征识别:")
        logger.info(f"  - 低效特征 (|IC|<0.01): {len(zero_importance_features)} 个")
        if zero_importance_features:
            for feature in zero_importance_features[:5]:
                logger.info(f"    * {feature}")
            if len(zero_importance_features) > 5:
                logger.info(f"    * ... 还有 {len(zero_importance_features) - 5} 个")

        logger.info(f"  - 高相关性特征: {len([f for f, _, _ in high_corr_pairs])} 个")
        logger.info(f"  - 高VIF特征: {len(high_vif_features)} 个")

        # 4. 优化建议
        logger.info(f"\n[IDEA] 优化建议:")

        if len(zero_importance_features) > 0:
            logger.info(f"  1. 特征筛选:")
            logger.info(f"     - 移除 {len(zero_importance_features)} 个低效交互特征")
            logger.info(f"     - 保留 {len(effective_features)} 个有效交互特征")

        if len(high_corr_pairs) > 0:
            logger.info(f"  2. 相关性处理:")
            logger.info(f"     - 发现 {len(high_corr_pairs)} 对高相关性特征")
            logger.info(f"     - 建议使用相关性筛选或PCA降维")

        if len(high_vif_features) > 0:
            logger.info(f"  3. 多重共线性处理:")
            logger.info(f"     - {len(high_vif_features)} 个特征存在多重共线性")
            logger.info(f"     - 建议使用岭回归或LASSO进行特征选择")

        # 5. 模型参数调整建议
        logger.info(f"\n[WRENCH] 模型参数调整建议:")

        feature_increase_ratio = len(interaction_names) / len(stock_features)
        logger.info(f"  - 特征维度增加: {feature_increase_ratio:.1f}x ({len(stock_features)} -> {len(stock_features) + len(interaction_names)})")

        if feature_increase_ratio > 2.0:
            logger.info(f"  - 建议增加正则化强度:")
            logger.info(f"    * L2正则化 (lambda): 1.0 -> 2.0-5.0")
            logger.info(f"    * L1正则化 (alpha): 0.0 -> 0.1-0.5")
            logger.info(f"  - 建议降低模型复杂度:")
            logger.info(f"    * max_depth: 5 -> 3-4")
            logger.info(f"    * eta (学习率): 0.1 -> 0.05-0.08")

        # 6. 管线评估改进建议
        logger.info(f"\n[CHART] 管线评估改进建议:")
        logger.info(f"  - 当前指标: Top10%-Bottom10%")
        logger.info(f"  - 建议补充指标:")
        logger.info(f"    * IC_IR综合得分: IC均值 / IC标准差")
        logger.info(f"    * 夏普比率: 收益均值 / 收益标准差")
        logger.info(f"    * 最大回撤: 评估风险控制能力")
        logger.info(f"    * 胜率: 预测正确的比例")

        # 7. 串联过滤结果展示
        if final_ranked_features is not None and filtering_results is not None:
            logger.info(f"\n[REFRESH] 串联过滤结果:")
            logger.info(f"  - 原始交互特征: {filtering_results['original_features']} 个")
            logger.info(f"  - 质量检查后: {filtering_results['valid_features_after_quality_check']} 个")
            logger.info(f"  - 相关性过滤后: {filtering_results['features_after_correlation_filter']} 个")
            logger.info(f"  - VIF过滤后: {filtering_results['features_after_vif_filter']} 个")
            logger.info(f"  - 最终保留: {filtering_results['final_ranked_features']} 个")
            logger.info(f"  - 总体保留率: {filtering_results['filtering_summary']['final_retention_rate']:.2%}")

            logger.info(f"\n[TROPHY] 最终优质交互特征 (前10名):")
            for i, feature_info in enumerate(final_ranked_features[:10], 1):
                feature_name = feature_info['feature']
                ic = feature_info['ic']
                ic_abs = feature_info['ic_abs']
                logger.info(f"  {i:2d}. {feature_name}: IC={ic:.4f} (|IC|={ic_abs:.4f})")

            if len(final_ranked_features) > 10:
                logger.info(f"  ... 还有 {len(final_ranked_features) - 10} 个优质特征")

        # 8. 下一步行动计划
        logger.info(f"\n[TARGET] 下一步行动计划:")

        if final_ranked_features is not None and len(final_ranked_features) > 0:
            logger.info(f"  1. 立即行动:")
            logger.info(f"     - 使用 {len(final_ranked_features)} 个优质交互特征重新训练")
            logger.info(f"     - 优先使用前10名特征进行初步验证")
            logger.info(f"     - 调整正则化参数防止过拟合")
        elif len(effective_features) > 0:
            logger.info(f"  1. 立即行动:")
            logger.info(f"     - 使用 {len(effective_features)} 个有效交互特征重新训练")
            logger.info(f"     - 调整正则化参数防止过拟合")

        if len(zero_importance_features) > len(effective_features):
            logger.info(f"  2. 特征工程优化:")
            logger.info(f"     - 尝试不同的股票特征组合")
            logger.info(f"     - 测试非线性交互 (比值、差值、条件交互)")
            logger.info(f"     - 引入时间滞后的交互特征")

        logger.info(f"  3. 验证测试:")
        logger.info(f"     - 在独立测试集上验证改进效果")
        logger.info(f"     - 对比有无交互特征的回测结果")
        logger.info(f"     - 监控过拟合风险")

        logger.info("=" * 80)
        logger.info("[OK] 交互特征全面分析完成")
        logger.info("=" * 80)

        return True

    except Exception as e:
        logger.error(f"[FAIL] 报告生成失败: {e}")
        import traceback
        logger.error(f"详细错误: {traceback.format_exc()}")
        return False


def _cs_label_formula_signature():
    """对标签生成函数源码做md5：任何标签公式改动自动使搜索缓存失效。

    之前靠手动改CS_LABEL_SIGNATURE，用户手改公式（如惩罚阈值/系数）时容易漏改，
    导致跨窗口运行复用旧标签的搜索分。改为直接哈希源码，一劳永逸。
    """
    import hashlib
    import inspect
    try:
        src = inspect.getsource(_generate_training_labels_for_all_data)
        return hashlib.md5(src.encode("utf-8")).hexdigest()[:12]
    except Exception:
        return CS_LABEL_SIGNATURE


def _cs_training_signature(params, window_dates, feature_columns=None):
    """[v65-perf] 候选训练签名：仅含影响候选训练结果的项（窗口日期/标签/权重/早停/轮数/特征/参数）。

    用途：缓存键含门槛/score等大量非训练常量——它们变化会使键失效触发全量重搜，
    但候选训练结果其实不变。按签名匹配旧缓存的同参候选即可跳过重训（参数复用）。
    注意与 _cs_search_cache_key 的区别：那个是"整包失效"，这个是"训练等价性"。
    """
    import hashlib
    _payload = {
        "dates": [str(x) for x in (window_dates or ())],
        "label_round": [CS_LABEL_FAMILY, CS_LABEL_PCT, CS_LABEL_RISK_RATIO,
                        CS_LABEL_MINUTE_COV_FLOOR,
                        sorted((k, tuple(sorted(v.items())))
                               for k, v in CS_LABEL_FAMILY_CFG.items())],
        "weight": [WEIGHT_ENABLE_TIME_DECAY, WEIGHT_TIME_DECAY_HALF_LIFE_DAYS,
                   WEIGHT_DAILY_HEAD_K, WEIGHT_DAILY_HEAD_MULTIPLIER,
                   WEIGHT_HEAD_MODE, WEIGHT_DAILY_HEAD_PCT,
                   WEIGHT_HEAD_ENABLE_GAP_EXCLUDE, WEIGHT_HEAD_EXCLUDE_GAP_UP,
                   WEIGHT_HEAD_EXCLUDE_GAP_DOWN, WEIGHT_HEAD_ADAPTIVE_DIFF,
                    WEIGHT_HEAD_DIFF_REF,
                    CS_TAIL_WEIGHT_ENABLE, CS_TAIL_WEIGHT_ALPHA, CS_TAIL_WEIGHT_R0,
                    # [v66-fix] 训练签名必须含 regime 降权常量——否则权重变更后旧模型被误复用
                    CS_REGIME_SHRINK_ENABLE, CS_REGIME_SHRINK_W_MIN,
                    # [v67] 稀缺日加权同样影响候选训练结果
                    CS_REGIME_BOOST_ENABLE, CS_REGIME_BOOST_MAX,
                    CS_REGIME_SHRINK_POWER, CS_REGIME_SHRINK_REF_Q],
        "early_stop": [CS_EARLY_STOP_METRIC, CS_EARLY_STOP_AP_K,
                       CS_EARLY_STOP_NDCG_K, CS_EARLY_STOP_NDCG_K2,
                       CS_EARLY_STOP_NDCG_EMA_SPAN, CS_EARLY_STOP_NDCG_MIN_GROUP,
                       CS_EARLY_STOP_NDCG_MIN_UNIQUE,
                       # [v73] 大亏惩罚影响早停best_iter，必须入键（此前遗漏→改W不失效旧缓存）
                       CS_EARLY_STOP_BIG_LOSS_PENALTY, CS_EARLY_STOP_BIG_LOSS_WEIGHT,
                       CS_EARLY_STOP_BIG_LOSS_THRESHOLD,
                       # [v73] TopK收益质量早停主信号入键（改模式/K/winsor必须失效旧缓存）
                       CS_EARLY_STOP_RETURN_MODE, CS_EARLY_STOP_RETURN_K,
                       CS_EARLY_STOP_RETURN_WINSOR, CS_EARLY_STOP_RETURN_EPS],
        "boost": LGB_SEARCH_MAX_BOOST_ROUNDS,
        "feats": sorted(str(x) for x in (feature_columns or [])),
        "params": sorted((k, str(v)) for k, v in dict(params or {}).items()),
    }
    return hashlib.md5(repr(_payload).encode("utf-8")).hexdigest()[:12]


def _cs_collect_searched_param_keys(window_idx):
    """[v65-perf] --fresh_search：收集同窗口所有历史缓存中已搜索候选的参数冻结键。
    返回 (排除键集合, 排除集指纹md5)。文件缺失/损坏容忍（跳过）。"""
    import glob as _glob
    import pickle as _pickle
    import hashlib
    keys = set()
    if window_idx is None:
        return keys, None
    for _pf in _glob.glob(f"results/cs_search_w{window_idx}_*.pkl"):
        try:
            with open(_pf, "rb") as _hf:
                _old = _pickle.load(_hf)
            _oc = (_old or {}).get("_cand") if isinstance(_old, dict) else None
            for _orec in (_oc or {}).values():
                _p = (_orec or {}).get("params")
                if _p:
                    keys.add(tuple(sorted((k, str(v)) for k, v in dict(_p).items())))
        except Exception:
            continue
    fp = hashlib.md5(repr(sorted(keys)).encode("utf-8")).hexdigest()[:8] if keys else None
    return keys, fp


def _cs_search_cache_key(window_dates, confirm_eval=False):
    """阶段1搜索缓存键：窗口日期 + 所有选参/评分/权重相关常量。

    修改下列任一配置后哈希会变化，自动失效；修改选参逻辑本身请同时+1 CS_CACHE_VERSION。
    """
    import hashlib
    search_space, _ = _get_lgb_search_space()
    payload = {
        "v": CS_CACHE_VERSION,
        "dates": [str(x) for x in (window_dates or ())],        "confirm_eval": bool(confirm_eval),
        "multifold": [CS_MULTIFOLD_ENABLE, CS_MULTIFOLD_K, CS_MULTIFOLD_MIN_TRAIN_DAYS,
                      CS_LABEL_PURGE_TRADE_DAYS],
        "search": [LGB_SEARCH_CANDIDATE_COUNT, LGB_SEARCH_RANDOM_STATE,
                   LGB_SEARCH_MAX_BOOST_ROUNDS,
                   sorted((k, sorted(str(v) for v in vals))
                          for k, vals in search_space.items())],
        "score": [CS_SCORE_NDCG_K, CS_SCORE_TOP_EXCESS_FRAC, CS_SCORE_EXCESS_FULL_SCALE,
                  CS_IC_T_FULL_SCALE, CS_RANKIC_FULL_SCALE, CS_HEAD_EXCESS_FULL_SCALE,
                  CS_HEAD_WINRATE_IMPROVEMENT,
                  CS_SCORE_WEIGHT_IC_T, CS_SCORE_WEIGHT_RANKIC,
                  CS_SCORE_WEIGHT_EXCESS, CS_SCORE_WEIGHT_HEAD],
        "guard": [OVERFIT_GUARD_ENABLE, CS_GUARD_RATIO_TOL, CS_GUARD_RATIO_SPAN,
                  CS_GUARD_IC_T_MIN, CS_GUARD_IC_T_FLOOR, CS_GUARD_PENALTY_MAX,
                  CS_FOLD_SCORE_FLOOR],
        "binary_v55": [CS_EARLY_STOP_NDCG_K, CS_EARLY_STOP_NDCG_K2,
                       CS_EARLY_STOP_NDCG_EMA_SPAN, CS_EARLY_STOP_NDCG_MIN_GROUP,
                       CS_EARLY_STOP_NDCG_MIN_UNIQUE,
                       # [v64-fix] 早停主指标常量必须入键（此前漏 CS_EARLY_STOP_METRIC/AP_K，
                       # 改AP@K不会失效旧缓存，会复用旧早停训练的模型——AP@50→5时必踩）
                       CS_EARLY_STOP_METRIC, CS_EARLY_STOP_AP_K,
                       CS_TREE_FLOOR, CS_TREE_CAP, CS_TREE_GRID_MULTS,
                       CS_TREE_GRID_MARGIN, CS_MIN_BEST_ITER,
                       CS_BINARY_GUARD_ENABLE, CS_BINARY_GUARD_TOL,
                       CS_BINARY_GUARD_SPAN, CS_BINARY_GUARD_PENALTY_MAX,
                       # [v72] 大亏惩罚影响早停best_iter，必须入键（否则改W后整包键不变→命中旧缓存复用旧模型）
                       CS_EARLY_STOP_BIG_LOSS_PENALTY, CS_EARLY_STOP_BIG_LOSS_WEIGHT,
                       CS_EARLY_STOP_BIG_LOSS_THRESHOLD,
                       # [v73] TopK收益质量早停主信号入键（改模式/K/winsor必须失效旧缓存）
                       CS_EARLY_STOP_RETURN_MODE, CS_EARLY_STOP_RETURN_K,
                       CS_EARLY_STOP_RETURN_WINSOR, CS_EARLY_STOP_RETURN_EPS,
CS_BINARY_GATE_T_MIN, CS_BINARY_GATE_MEDIAN_MIN,
                        CS_BINARY_GATE_MDD_MAX, CS_BINARY_SCORE_INCLUDE_HIT,
                        CS_BINARY_MIN_EVIDENCE_T, CS_BINARY_MIN_EVIDENCE_MEDIAN],
        "binary_v58": [CS_NULL_DRAWS, CS_NULL_SEED,
                       CS_TOPNULL_GATE_Z_T, CS_TOPNULL_GATE_POS_SHARE,
                       CS_TOPNULL_FOLD0_VETO_Z_T, CS_TOPNULL_SWAP_DEPLOY_Z_T,
                       CS_TOPNULL_DEPLOY_Z_T, CS_TOPNULL_DEPLOY_POS_SHARE,
                       CS_CROSS_WINDOW_EVIDENCE_Z_T, CS_STOP_DISASTER_MAX],
        "confirm": [CS_CONFIRM_ENABLE, CS_CONFIRM_FRAC, CS_CONFIRM_MIN_DAYS],
        "label": [_cs_label_formula_signature(), REGRESSION_CS_LABEL_MODE,
                  REGRESSION_CS_Z_CLIP, REGRESSION_LABEL_CAP,
                  REGRESSION_DRAWDOWN_PENALTY_ENABLE,
                  REGRESSION_DRAWDOWN_PENALTY_THRESHOLD],
        "label_round": [CS_LABEL_FAMILY, CS_LABEL_PCT, CS_LABEL_RISK_RATIO,
                        CS_LABEL_MINUTE_COV_FLOOR,
                        sorted((k, tuple(sorted(v.items())))
                               for k, v in CS_LABEL_FAMILY_CFG.items())],
        "weight": [WEIGHT_ENABLE_TIME_DECAY, WEIGHT_TIME_DECAY_HALF_LIFE_DAYS,
                   WEIGHT_DAILY_HEAD_K, WEIGHT_DAILY_HEAD_MULTIPLIER,
                   WEIGHT_HEAD_MODE, WEIGHT_DAILY_HEAD_PCT,
                   WEIGHT_HEAD_ENABLE_GAP_EXCLUDE, WEIGHT_HEAD_EXCLUDE_GAP_UP,
                   WEIGHT_HEAD_EXCLUDE_GAP_DOWN, WEIGHT_HEAD_ADAPTIVE_DIFF,
                   WEIGHT_HEAD_DIFF_REF,
                   CS_TAIL_WEIGHT_ENABLE, CS_TAIL_WEIGHT_ALPHA, CS_TAIL_WEIGHT_R0,
                   # [v66-阶段1] regime降权影响候选训练结果，必须入键（全量重训为必要代价）
                   CS_REGIME_SHRINK_ENABLE, CS_REGIME_SHRINK_W_MIN, CS_REGIME_SHRINK_POWER,
                   # [v67] 稀缺日加权同样影响训练结果
                   CS_REGIME_BOOST_ENABLE, CS_REGIME_BOOST_MAX,
                   CS_REGIME_SHRINK_REF_Q],
    }
    # [v65-perf] 仅 fresh 模式注入排除集指纹（普通运行键保持与历史完全一致，不触发重搜）
    if globals().get('_CS_FRESH_EXCL_FP'):
        payload["fresh_fp"] = globals()['_CS_FRESH_EXCL_FP']
    return hashlib.md5(repr(payload).encode("utf-8")).hexdigest()[:12]


def _swap_parallel_config():
    """[SWAP-PARALLEL] 返回 (workers, 每worker的LightGBM num_threads)。
    workers<=1 = 串行（完全保持原行为）。"""
    import os
    _cpus = max(1, int(os.cpu_count() or 1))
    _workers = int(CS_SWAP_PARALLEL_WORKERS or 0)
    if _workers <= 0:
        return 1, None
    _workers = min(_workers, _cpus)
    if _workers <= 1:
        return 1, None
    if CS_SWAP_PARALLEL_NUM_THREADS:
        _threads = max(1, int(CS_SWAP_PARALLEL_NUM_THREADS))
    else:
        _threads = max(1, int(math.ceil(_cpus / _workers)))
    return _workers, _threads


def _swap_cache_fingerprint():
    """[SWAP-CACHE] 影响 swap 折重训结果的配置指纹：任一变化即失效重算。
    只含影响指标的项（折窗口/候选数/零分布）；门槛常量变化不需重训。
    [v65-fix] workers/threads 从指纹移除：并行配置不改变指标（LightGBM 训练确定性），
    改 worker 数不应使 swap 缓存失效（否则调优并发=被迫重算全部 91 折）。"""
    import hashlib
    _p = {
        "top_k": CS_MULTIFOLD_SWAP_TOP_K,
        "gate_ok_first": bool(CS_SWAP_GATE_OK_PRIORITY),  # [v61-deploy] top-K 选择优先 FOLD1 过门者
        "min_folds": CS_MULTIFOLD_SWAP_MIN_FOLDS,
        "main_train_end": MFOLD_SWAP_MAIN_TRAIN_END,
        "hole_val": MFOLD_SWAP_HOLE_VAL,
        "month_train": MFOLD_SWAP_MONTH_TRAIN,
        "month_val": MFOLD_SWAP_MONTH_VAL,
        "config": MFOLD_SWAP_CONFIG,
        "f1_gate": [CS_TOPNULL_GATE_Z_T, CS_BINARY_GATE_MDD_MAX, CS_MIN_BEST_ITER,
                    "wide-v61"],  # [v70]分段否决删除属门槛重评层变更，swap折指标语义不变，指纹保持（否则已算好的006/012/002七折会白白重算）
        "null_draws": CS_NULL_DRAWS,
        "null_seed": CS_NULL_SEED,
        "sem": "v70-unified4",  # [v70] 统一4月深度+历史月份覆盖：折结构变更，旧缓存失效
    }
    return hashlib.md5(repr(_p).encode("utf-8")).hexdigest()[:12]


def _cs_search_cache_save(window_idx, window_dates, candidate_records, confirm_eval=False, swap_metrics=None):
    """保存某窗口阶段1的多折候选评分（含确认段评分）。
    [SWAP-CACHE] swap_metrics 非空时一并落盘（同一窗口缓存文件，跨标签族自动隔离：
    缓存键已含 label_round 载荷，不同标签方案=不同文件名，swap 指标永不串用）。"""
    import pickle
    from pathlib import Path
    logger = logging.getLogger(__name__)
    try:
        if not candidate_records:
            return
        p = Path("results") / (
            f"cs_search_w{window_idx}_{_cs_search_cache_key(window_dates, confirm_eval)}.pkl"
        )
        if swap_metrics:
            _blob = {
                "_cand": dict(candidate_records),
                "_swap_metrics": swap_metrics,
                "_swap_fp": _swap_cache_fingerprint(),
            }
        else:
            _blob = dict(candidate_records)
        with open(p, "wb") as f:
            pickle.dump(_blob, f)
        logger.info(f"[CS-CACHE] 已保存窗口{window_idx}搜索缓存: {p.name}")
    except Exception as _e:
        logger.warning(f"[CS-CACHE] 保存窗口{window_idx}搜索缓存失败: {_e}")


def _cs_search_cache_load(window_idx, window_dates, confirm_eval=False):
    """命中则返回该窗口缓存的候选评分，否则返回None。兼容新旧两种格式。"""
    import pickle
    from pathlib import Path
    logger = logging.getLogger(__name__)
    try:
        p = Path("results") / (
            f"cs_search_w{window_idx}_{_cs_search_cache_key(window_dates, confirm_eval)}.pkl"
        )
        if p.exists():
            with open(p, "rb") as f:
                data = pickle.load(f)
            if isinstance(data, dict) and data:
                _cand = data.get("_cand") if "_cand" in data else data
                if isinstance(_cand, dict) and _cand:
                    logger.info(
                        f"[CS-CACHE] 命中窗口{window_idx}搜索缓存: {p.name} (候选{len(_cand)})"
                    )
                    return _cand
    except Exception as _e:
        logger.warning(f"[CS-CACHE] 加载窗口{window_idx}搜索缓存失败: {_e}")
    return None


def _cs_search_swap_metrics_load(window_idx, window_dates, confirm_eval=False):
    """[SWAP-CACHE] 读取窗口缓存中的 swap 指标（含指纹）。
    不存在/格式不符返回 (None, None)。"""
    import pickle
    from pathlib import Path
    logger = logging.getLogger(__name__)
    try:
        p = Path("results") / (
            f"cs_search_w{window_idx}_{_cs_search_cache_key(window_dates, confirm_eval)}.pkl"
        )
        if p.exists():
            with open(p, "rb") as f:
                data = pickle.load(f)
            if isinstance(data, dict) and data.get("_swap_metrics") and data.get("_swap_fp"):
                return data["_swap_metrics"], data["_swap_fp"]
    except Exception as _e:
        logger.warning(f"[SWAP-CACHE] 加载swap缓存失败: {_e}")
    return None, None


def _select_cross_window_best(registry):
    """跨窗口一致性选参。

    优先稳定性（候选须在每个窗口进入TopK，缺失窗口记为末位），
    再取 global = mean(窗口分) - 0.5×std(窗口分)；接近时用奥卡姆判据
    （更少叶子/更大min_data/更强正则）打破平局。
    """
    import numpy as np
    logger = logging.getLogger(__name__)
    if not registry:
        return None

    # —— [CS-SELECT] 窗口证据门槛：无信号窗口不参与一致性评分 ——
    # [v58] 只考虑通过FOLD1门槛(gate_ok)的候选；证据判据=相对（窗口最佳FOLD1 top5-null z_t）。
    usable_windows = []
    for w in sorted(registry.keys()):
        _gate_ok_recs = [
            rec for rec in registry[w].values()
            if isinstance(rec, dict) and rec.get('fold_gate_ok')
        ]
        if not _gate_ok_recs:
            logger.warning(f"[CS-SELECT] Window {w} 无过门槛候选，该窗口不参与一致性评分")
            continue
        _win_best = max(
            float((rec.get('fold_raw') or [{}])[-1].get('top5_null_z_t', np.nan)
                 if isinstance(rec.get('fold_raw'), list) and rec.get('fold_raw') else np.nan)
            for rec in _gate_ok_recs
        )
        if np.isfinite(_win_best) and _win_best >= CS_CROSS_WINDOW_EVIDENCE_Z_T:
            usable_windows.append(w)
        else:
            logger.warning(
                f"[CS-SELECT] Window {w} 无有效信号（最佳候选FOLD1 z_t {_win_best:.3f} < 证据门槛 "
                f"{CS_CROSS_WINDOW_EVIDENCE_Z_T:.2f}），该窗口不参与一致性评分"
            )
    if len(usable_windows) < CS_CROSS_WINDOW_MIN_WINDOWS:
        logger.warning(
            f"[CS-SELECT] 有效证据窗口仅 {len(usable_windows)} 个（<{CS_CROSS_WINDOW_MIN_WINDOWS}），"
            f"回退使用全部窗口参与评分"
        )
        usable_windows = sorted(registry.keys())

    common = None
    for w in usable_windows:
        keys = set(
            c for c, rec in registry[w].items()
            if isinstance(rec, dict) and rec.get('fold_gate_ok')
        )
        common = keys if common is None else (common & keys)
    if not common:
        logger.warning("[CS-SELECT] 有效窗口无共同候选，无法一致性选参")
        return None

    rows = []
    for c in sorted(common):
        wins = [(w, registry[w][c]) for w in usable_windows]
        scores = np.asarray([rec['score'] for _, rec in wins], dtype=float)
        ranks = []
        for w, rec in wins:
            # [v58] 排名池只含过门槛候选（与common键一致）
            window_scores = sorted(
                (r['score'] for r in registry[w].values()
                 if isinstance(r, dict) and r.get('fold_gate_ok')),
                reverse=True,
            )
            rank = next(
                (i + 1 for i, s in enumerate(window_scores) if abs(s - rec['score']) < 1e-12),
                len(window_scores),
            )
            ranks.append(rank)
        mean_s = float(np.mean(scores))
        std_s = float(np.std(scores))
        min_s = float(np.min(scores))
        mean_rank = float(np.mean(ranks))
        top_k_count = int(sum(1 for r in ranks if r <= CS_CROSS_WINDOW_TOP_K))
        global_score = mean_s - CS_CROSS_WINDOW_STD_PENALTY * std_s
        params = dict(wins[0][1].get('params', {}))
        params['_candidate_id'] = c
        rows.append({
            'candidate_id': c,
            'params': params,
            'mean_score': mean_s,
            'std_score': std_s,
            'min_score': min_s,
            'mean_rank': mean_rank,
            'top_k_count': top_k_count,
            'global_score': global_score,
            'scores_by_window': {w: rec['score'] for w, rec in wins},
            'best_iteration_by_window': {},
        })

    rows.sort(key=lambda r: (-r['top_k_count'], -r['global_score'], r['mean_rank']))
    best = rows[0]
    # 奥卡姆平局判据：同稳定性且global分差在2%内时，选更简单的候选
    tol = 0.02 * max(abs(best['global_score']), 1e-9)
    for r in rows[1:]:
        if r['top_k_count'] < best['top_k_count']:
            break
        if (best['global_score'] - r['global_score'] <= tol
                and _cs_parsimony_key(r['params']) < _cs_parsimony_key(best['params'])):
            best = r

    # —— [CS-CONFIRM] 最终测试期确认段门控（champion-challenger）——
    # 全局最佳候选须在最后窗口测试期开头段的排序质量上进入候选池TopK，
    # 否则从全局Top池中回退到确认段表现最好的候选。
    if CS_CONFIRM_ENABLE and registry:
        confirm_win = max(registry.keys())
        confirm_map = {}
        for _c, _rec in registry[confirm_win].items():
            if not isinstance(_rec, dict):
                continue
            _cf = _rec.get('confirm')
            if isinstance(_cf, dict) and np.isfinite(_cf.get('score', np.nan)):
                confirm_map[_c] = float(_cf['score'])
        if confirm_map:
            for r in rows:
                r['confirm_score'] = confirm_map.get(r['candidate_id'], float('nan'))
            # 确认段无信号判定：所有候选确认段 top5-null z_t（二分类）/ ic_t（回归）最大值须为正
            # 才认为有信号，否则排名只是 0.000~0.012 之间的噪声，门控不应据此"通过/回退"。
            _confirm_sig_ts = []
            for _c, _rec in registry[confirm_win].items():
                if not isinstance(_rec, dict):
                    continue
                _cf = _rec.get('confirm')
                if not isinstance(_cf, dict):
                    continue
                _sig = _cf.get('top5_null_z_t', _cf.get('ic_t', np.nan))
                if np.isfinite(_sig):
                    _confirm_sig_ts.append(float(_sig))
            if not _confirm_sig_ts or max(_confirm_sig_ts) <= CS_CONFIRM_IC_T_MIN_SIGNAL:
                logger.warning(
                    f"[CS-CONFIRM-GATE] 确认段无有效信号（候选top5-null z_t/ic_t范围 "
                    f"{min(_confirm_sig_ts) if _confirm_sig_ts else float('nan'):.2f}~"
                    f"{max(_confirm_sig_ts) if _confirm_sig_ts else float('nan'):.2f}），"
                    f"门控不提供信息，保持全局最佳 {best['candidate_id']}"
                )
            else:
                confirm_sorted = sorted(
                    rows,
                    key=lambda r: (np.isfinite(r['confirm_score']), r['confirm_score']),
                    reverse=True,
                )
                best_rank = next(
                    (i + 1 for i, r in enumerate(confirm_sorted)
                     if r['candidate_id'] == best['candidate_id']),
                    len(confirm_sorted) + 1,
                )
                logger.info(
                    f"[CS-CONFIRM-GATE] 全局最佳 {best['candidate_id']} 在确认段排名 "
                    f"{best_rank}/{len(confirm_sorted)} (Top{CS_CONFIRM_TOP_K} 通过)"
                )
                if best_rank > CS_CONFIRM_TOP_K:
                    pool = rows[:max(1, int(CS_CONFIRM_POOL))]
                    pool_ok = [r for r in pool if np.isfinite(r.get('confirm_score', np.nan))]
                    if pool_ok:
                        fallback = max(pool_ok, key=lambda r: r['confirm_score'])
                        logger.warning(
                            f"[CS-CONFIRM-GATE] 回退: {best['candidate_id']} (确认段 "
                            f"{best.get('confirm_score', float('nan')):.4f}) -> "
                            f"{fallback['candidate_id']} (确认段 {fallback['confirm_score']:.4f})"
                        )
                        best = fallback
                    else:
                        logger.warning("[CS-CONFIRM-GATE] 回退池无有效确认段评分，保持原全局最佳")
        else:
            logger.info("[CS-CONFIRM] 确认段评分缺失，跳过门控")

    # 每窗口的最终重训轮数 = 该窗口内该候选各折best_iteration的中位数
    all_bits = []
    for w in sorted(registry.keys()):
        rec = registry[w].get(best['candidate_id'])
        if not rec:
            continue
        bits = [int(b) for b in (rec.get('best_iterations') or []) if int(b) > 0]
        if bits:
            # 最后一折=窗口真实验证期折，其训练集=完整训练期，与搜索模式的最终重训口径一致
            best['best_iteration_by_window'][w] = int(bits[-1])
            all_bits.extend(bits)
    default_bit = int(np.median(all_bits)) if all_bits else 0
    for w in sorted(registry.keys()):
        best['best_iteration_by_window'].setdefault(w, default_bit)

    logger.info("=" * 80)
    logger.info("[CS-SELECT] 跨窗口候选榜（窗口分为0-1尺度，已扣护栏）:")
    header = (f"    {'候选':<12}{'窗口分':<46}{'mean':>7}{'std':>7}{'min':>7}"
              f"{'meanRank':>9}{'TopK':>6}{'global':>9}")
    logger.info(header)
    for r in sorted(rows, key=lambda x: (-x['top_k_count'], -x['global_score'])):
        win_s = " ".join(
            f"W{w}:{r['scores_by_window'].get(w, float('nan')):.3f}"
            for w in usable_windows
        )
        logger.info(
            f"    {r['candidate_id']:<12}{win_s:<46}{r['mean_score']:>7.3f}{r['std_score']:>7.3f}"
            f"{r['min_score']:>7.3f}{r['mean_rank']:>9.2f}{r['top_k_count']:>6}{r['global_score']:>9.3f}"
        )
    logger.info(
        "[CS-SELECT] 最优稳定候选: %s | mean=%.4f std=%.4f min=%.4f mean_rank=%.2f "
        "top%d_count=%d | best_iter_by_window=%s",
        best['candidate_id'], best['mean_score'], best['std_score'], best['min_score'],
        best['mean_rank'], CS_CROSS_WINDOW_TOP_K, best['top_k_count'],
        best['best_iteration_by_window'],
    )
    logger.info("=" * 80)
    return best


def run_test_model_walkforward_mode(args):
    """
    运行Walk-Forward Analysis + 交叉验证模式

    实现顶级量化机构的标准做法:
    1. 将回测期分成多个窗口
    2. 每个窗口执行完整的"贝叶斯搜索(带交叉验证)+训练+回测"流程
    3. 汇总所有窗口的回测结果

    Args:
        args: 命令行参数
    """
    logger = logging.getLogger(__name__)
    print(f"运行模式: Walk-Forward Analysis + 交叉验证")
    logger.info("=" * 80)
    logger.info("顶级量化机构标准做法: 滚动优化 + 交叉验证")
    logger.info("=" * 80)

    try:
        global ENABLE_WALKFORWARD_DAILY_MEDIAN_NEUTRALIZE
        ENABLE_WALKFORWARD_DAILY_MEDIAN_NEUTRALIZE = False
        logger.info(
            "[中位数替换] test_model_walkforward已启用，以下因子在输入模型前会替换为当日横截面中位数: "
            f"{', '.join(WALKFORWARD_DAILY_MEDIAN_NEUTRALIZE_FACTORS)}"
        )

        import pandas as pd
        import numpy as np
        from pathlib import Path
        from datetime import datetime

        # [WRENCH] 修复：定义Walk-Forward扩展窗口（Expanding Window）
        # 每个窗口包含: 训练集、验证集(用于超参数搜索)、测试集(用于回测)
        # 时间序列原则: 训练集 < 验证集 < 测试集 (无重叠,无数据泄露)
        # 扩展窗口特点: 训练期从固定起点开始，逐渐增加训练数据量
        windows = [
            # [CS-WINDOWS] 修正版选项1：三个窗口的验证期/测试期完全互不重叠，
            #   W1/W2/W3的训练为扩展窗口（W2训练包含W1的val+test，W3训练包含W2的test）。
            #   W3验证期=2025-04~07（含4月调整行情），W3测试期=最终部署期。
            {
                'name': 'Window 1',
                'train_start': '2023-06-01',
                'train_end': '2024-03-31',
                'val_start': '2024-04-01',
                'val_end': '2024-06-30',
                'test_start': '2024-07-01',
                'test_end': '2024-09-30'
            },
            {
                'name': 'Window 2',
                'train_start': '2023-06-01',
                'train_end': '2024-09-30',
                'val_start': '2024-10-01',
                'val_end': '2024-12-31',
                'test_start': '2025-01-01',
                'test_end': '2025-03-31'
            },
            {
                'name': 'Window 3',
                'train_start': '2023-06-01',
                'train_end': '2025-03-31',
                'val_start': '2025-04-01',
                'val_end': '2025-07-25',
                'test_start': '2025-08-01',
                'test_end': '2026-05-18'
            },
        ]

        # [WRENCH] 解析窗口选择参数
        selected_window_indices = None
        if args.window:
            try:
                # 解析窗口编号（支持逗号分隔，如 "1" 或 "1,3"）
                selected_window_indices = [int(w.strip()) for w in args.window.split(',')]

                # 验证窗口编号范围
                for idx in selected_window_indices:
                    if idx < 1 or idx > len(windows):
                        logger.error(f"[FAIL] 窗口编号 {idx} 超出范围 [1, {len(windows)}]")
                        return False

                logger.info(f"\n[TARGET] 窗口选择模式: 只训练指定的窗口 {selected_window_indices}")
            except ValueError as e:
                logger.error(f"[FAIL] 窗口参数格式错误: {args.window}，应为数字或逗号分隔的数字（例如: 1 或 1,3）")
                return False
        else:
            logger.info(f"\n[TARGET] 默认模式: 训练所有窗口")

        logger.info(f"\n[CHART] Walk-Forward窗口配置:")
        logger.info(f"  总窗口数: {len(windows)}")
        if selected_window_indices:
            logger.info(f"  选择的窗口: {selected_window_indices}")
        else:
            logger.info(f"  选择的窗口: 全部")
        logger.info(f"  时间序列原则: 训练集 < 验证集 < 测试集 (无重叠)")
        for i, window in enumerate(windows, 1):
            # 标记是否被选中
            selected_mark = "✓" if (selected_window_indices is None or i in selected_window_indices) else "✗"
            logger.info(f"\n  [{selected_mark}] 窗口{i} ({window['name']}):")
            logger.info(f"    训练集: {window['train_start']} ~ {window['train_end']}")
            logger.info(f"    验证集: {window['val_start']} ~ {window['val_end']}")
            logger.info(f"    测试集: {window['test_start']} ~ {window['test_end']}")

        # 加载完整因子数据
        logger.info("\n[REFRESH] 加载完整因子数据...")
        factor_data = _load_factor_cache_data(include_label_generation_features=True)

        if factor_data is None or len(factor_data) == 0:
            logger.error("[FAIL] 因子数据加载失败")
            return False

        logger.info(f"[OK] 因子数据加载成功: {len(factor_data):,}条记录, {len(factor_data.columns)}个字段")
        logger.info(f"   日期范围: {factor_data['date'].min()} ~ {factor_data['date'].max()}")

        # 确保date列是datetime类型
        factor_data['date'] = pd.to_datetime(factor_data['date'])

        # [SW行业编码] 加载标准化SW申万行业数据用于LightGBM分类特征
        logger.info("\n[SW行业编码] 加载标准化SW申万行业数据...")

        encoding_data = load_standardized_sw_encoding()
        if not encoding_data:
            raise RuntimeError("无法加载标准化SW编码文件，请确保config/sw_industry_encoding.pkl文件存在")

        sw_sector_mapping = encoding_data['mappings']['stock_to_industry']

        metadata = encoding_data.get('metadata', {})
        logger.info(f"[OK] 标准化SW行业数据加载成功: {len(sw_sector_mapping)}只股票")
        logger.info(f"  版本: {metadata.get('version', 'unknown')}")
        logger.info(f"  生成时间: {metadata.get('generated_at', 'unknown')}")
        logger.info(f"  行业数: {metadata.get('total_industries', 0)}")

        # [SW编码检查] 检查SW行业编码20的分布
        logger.info("[SW编码检查] 开始检查SW行业编码20的分布...")
        if 'mappings' in encoding_data and 'industry_to_code' in encoding_data['mappings']:
            industry_to_code = encoding_data['mappings']['industry_to_code']
            sw_code_20_industries = [industry for industry, code in industry_to_code.items() if code == 20]
            logger.info(f"[SW编码检查] SW行业编码20对应行业: {sw_code_20_industries}")

            if 'stock_to_industry' in encoding_data['mappings']:
                stock_to_industry = encoding_data['mappings']['stock_to_industry']
                sw_code_20_stocks = [stock for stock, industry in stock_to_industry.items()
                                    if industry_to_code.get(industry) == 20]
                logger.info(f"[SW编码检查] SW行业编码20的股票总数: {len(sw_code_20_stocks)}")
                if sw_code_20_stocks:
                    logger.info(f"[SW编码检查] SW行业编码20股票示例: {sw_code_20_stocks[:10]}")
                else:
                    logger.warning("[SW编码检查] 警告：没有找到SW行业编码20的股票")
            else:
                logger.warning("[SW编码检查] 警告：编码数据中缺少stock_to_industry映射")
        else:
            logger.warning("[SW编码检查] 警告：编码数据格式不正确，无法检查SW行业编码20")

        # 存储所有窗口的回测结果
        all_window_results = []
        all_selections = []
        all_window_metrics = []

        # [CS-SELECT] 选中窗口列表
        selected_win_list = []
        for window_idx, window in enumerate(windows, 1):
            # [WRENCH] 如果指定了窗口选择，跳过未选中的窗口
            if selected_window_indices is not None and window_idx not in selected_window_indices:
                logger.info(f"\n⏭️  跳过 {window['name']} (未选中)")
                continue
            selected_win_list.append((window_idx, window))

        use_cross_window = (
            CS_CROSS_WINDOW_CONSISTENCY
            and len(selected_win_list) >= CS_CROSS_WINDOW_MIN_WINDOWS
        )

        def _run_windows(search_only, force_retrain, forced_params=None, forced_best_iterations=None, confirm_last_idx=None):
            local_results = []
            for window_idx, window in selected_win_list:
                # [FIX] 确认段只在阶段1的最后窗口评估；在循环体内按window_idx判断，
                #   避免在实参里引用外层残留的window_idx导致所有窗口都拿到同一个布尔值。
                _confirm_eff = bool(
                    search_only and confirm_last_idx is not None
                    and window_idx == confirm_last_idx
                )
                phase_tag = "[CS-SEARCH-ONLY]" if search_only else "[CS-FINAL]"
                logger.info("\n" + "=" * 80)
                logger.info(f"{phase_tag} 开始处理 {window['name']} (第{window_idx}/{len(windows)}个窗口)")
                logger.info("=" * 80)
                # [v23] 缓存加载：search_only 和 test_model_walkforward 都尝试命中
                # （test_model_walkforward命中后跳过搜索，用缓存的候选评分直接走选模/压力测试/否决/最终重训）
                _wd = (window['train_start'], window['train_end'],
                       window['val_start'], window['val_end'],
                       window['test_start'], window['test_end'])
                _cached = _cs_search_cache_load(window_idx, _wd, confirm_eval=_confirm_eff)
                if search_only and _cached is not None:
                    local_results.append((window_idx, window, {
                        'backtest_result': None,
                        'selections': [],
                        'metrics': {},
                        'candidate_scores': _cached,
                    }))
                    logger.info(f"[CS-SEARCH-ONLY] {window['name']} 命中搜索缓存，跳过搜索")
                    continue
                # [FIX] 在循环体内按window_idx取轮数，避免引用外层残留的window_idx
                forced_bit = (forced_best_iterations or {}).get(window_idx)
                if _cached is not None:
                    logger.info(
                        f"[CS-CACHE] {window['name']} 命中搜索缓存，跳过搜索直接选模+最终重训"
                    )
                window_result = _process_walkforward_window(
                    window, factor_data, args, window_idx, len(windows), windows,
                    sw_sector_mapping,
                    search_only=search_only,
                    forced_params=forced_params,
                    forced_best_iteration=forced_bit,
                    force_retrain=force_retrain,
                    confirm_eval=_confirm_eff,
                    cached_candidate_scores=_cached,
                )
                local_results.append((window_idx, window, window_result))
            return local_results

        global_best = None
        if use_cross_window:
            logger.info("\n" + "=" * 80)
            logger.info("[CS-SELECT] 阶段1：跨窗口一致性选参 - 各窗口多折搜索（只搜索，不训练最终模型/不回测）")
            logger.info("=" * 80)
            cross_window_scores = {}
            last_sel_idx = selected_win_list[-1][0] if selected_win_list else None
            for window_idx, window, window_result in _run_windows(
                search_only=True,
                force_retrain=True,
                confirm_last_idx=last_sel_idx,  # [CS-CONFIRM] 仅最后窗口评估确认段
            ):
                if window_result is None:
                    logger.error(f"[FAIL] {window['name']} 搜索阶段失败")
                    continue
                cands = window_result.get('candidate_scores') or {}
                cross_window_scores[window_idx] = cands
                logger.info(f"[CS-SEARCH-ONLY] {window['name']} 完成: 候选数={len(cands)}")

            if len(cross_window_scores) >= CS_CROSS_WINDOW_MIN_WINDOWS:
                global_best = _select_cross_window_best(cross_window_scores)
                if global_best is not None:
                    logger.info("\n" + "=" * 80)
                    logger.info("[CS-SELECT] 阶段2：使用全局一致性参数训练各窗口最终模型并回测")
                    logger.info("=" * 80)
                    for window_idx, window, window_result in _run_windows(
                        search_only=False,
                        force_retrain=True,
                        forced_params=global_best['params'],
                        forced_best_iterations=global_best['best_iteration_by_window'],
                    ):
                        if window_result is None:
                            logger.error(f"[FAIL] {window['name']} 最终阶段失败")
                            continue
                        all_window_results.append(window_result['backtest_result'])
                        all_selections.append({
                            'window_name': window['name'],
                            'selections': window_result['selections'],
                        })
                        all_window_metrics.append({
                            'window_name': window['name'],
                            'test_period': f"{window['test_start']} ~ {window['test_end']}",
                            **window_result['metrics'],
                        })
                        logger.info(f"[OK] {window['name']} 最终模型完成")
                else:
                    logger.error("[FAIL] 跨窗口一致性选参失败，回退单窗口流程")
                    use_cross_window = False
            else:
                logger.warning("[CS-SELECT] 完成搜索的窗口不足，回退单窗口流程")
                use_cross_window = False

        if not use_cross_window:
            for window_idx, window in selected_win_list:
                logger.info("\n" + "=" * 80)
                logger.info(f"[REFRESH] 开始处理 {window['name']} (第{window_idx}/{len(windows)}个窗口)")
                logger.info("=" * 80)
                # [v31] 单窗口分支也加载缓存（原bug：缓存加载在_run_windows内部，单窗口分支绕过）
                _wd_single = (window['train_start'], window['train_end'],
                              window['val_start'], window['val_end'],
                              window['test_start'], window['test_end'])
                _cached_single = _cs_search_cache_load(window_idx, _wd_single, confirm_eval=False)
                if _cached_single is not None:
                    logger.info(f"[CS-CACHE] {window['name']} 命中搜索缓存，跳过搜索直接选模+最终重训")
                window_result = _process_walkforward_window(
                    window, factor_data, args, window_idx, len(windows), windows, sw_sector_mapping,
                    cached_candidate_scores=_cached_single,
                )
                if window_result is None:
                    logger.error(f"[FAIL] {window['name']} 处理失败")
                    continue
                all_window_results.append(window_result['backtest_result'])
                all_selections.append({
                    'window_name': window['name'],
                    'selections': window_result['selections'],
                })
                all_window_metrics.append({
                    'window_name': window['name'],
                    'test_period': f"{window['test_start']} ~ {window['test_end']}",
                    **window_result['metrics'],
                })
                logger.info(f"[OK] {window['name']} 处理完成")

        # [CS-SELECT] 最终部署模型说明
        if global_best is not None and selected_win_list:
            last_idx, last_window = selected_win_list[-1]
            logger.info("\n" + "=" * 80)
            logger.info(
                "[FINAL-DEPLOY] 最终部署模型 = Window %d 最终模型（train+val: %s ~ %s, 全局候选=%s）",
                last_idx, last_window['train_start'], last_window['val_end'],
                global_best['candidate_id'],
            )
            logger.info(
                "[FINAL-DEPLOY] 全局一致性: mean=%.4f std=%.4f min=%.4f mean_rank=%.2f "
                "top%d_count=%d, best_iter_by_window=%s",
                global_best['mean_score'], global_best['std_score'], global_best['min_score'],
                global_best['mean_rank'], CS_CROSS_WINDOW_TOP_K, global_best['top_k_count'],
                global_best['best_iteration_by_window'],
            )
            logger.info("=" * 80)

        # 汇总所有窗口的结果
        logger.info("\n" + "=" * 80)
        logger.info("[CHART] Walk-Forward Analysis 汇总结果")
        logger.info("=" * 80)

        if not all_window_results:
            logger.error("[FAIL] 所有窗口处理失败,无法生成汇总结果")
            return False

        # 计算汇总指标
        _print_walkforward_summary(all_window_metrics)

        # 保存汇总结果
        _save_walkforward_results(all_window_metrics, all_selections)

        logger.info("[OK] Walk-Forward Analysis 完成")
        return True

    except Exception as e:
        logger.error(f"[FAIL] Walk-Forward Analysis 失败: {e}")
        import traceback
        logger.error(traceback.format_exc())
        return False


def run_pred_stocks_mode(args):
    """
    股票预测模式：根据指定日期预测top5股票

    Args:
        args: 命令行参数，必须包含--date参数
    """
    logger = logging.getLogger(__name__)

    # 验证必要参数
    if not hasattr(args, 'date') or not args.date:
        logger.error("pred_stocks模式需要指定--date参数")
        print("错误: pred_stocks模式需要指定--date参数 (格式: YYYYMMDD)")
        print("使用示例: python main.py --mode pred_stocks --date 20251216")
        return False

    prediction_date = args.date
    logger.info(f"运行模式: 股票预测 - 日期: {prediction_date}")
    print(f"运行模式: 股票预测")
    print(f"预测日期: {prediction_date}")
    print("=" * 60)

    try:
        import pandas as pd
        import numpy as np
        import pickle
        from pathlib import Path
        from datetime import datetime

        # 1. 加载预测日期的因子数据
        logger.info(f"步骤1: 加载 {prediction_date} 的因子数据")
        factor_data = _load_factor_data_for_prediction(prediction_date)

        if factor_data is None or factor_data.empty:
            logger.error(f"无法加载 {prediction_date} 的因子数据")
            print(f"错误: 无法加载 {prediction_date} 的因子数据")
            return False

        logger.info(f"成功加载因子数据: {len(factor_data)} 只股票")
        print(f"成功加载因子数据: {len(factor_data)} 只股票")

        # 2. 加载LightGBM模型
        logger.info("步骤2: 加载LightGBM模型")
        # model_path = Path("./results/lightgbm_model_window3_20251216_200900.pkl")_20260107_033514
        # model_path = Path("./results/lightgbm_model_window3_20251227_190526.pkl")
        model_path = Path("./results/lightgbm_model_window3_20260107_033514.pkl")
        model_path = Path("./results/lightgbm_model_window3_20260427_231053.pkl")


        if not model_path.exists():
            logger.error(f"模型文件不存在: {model_path}")
            print(f"错误: 模型文件不存在: {model_path}")
            return False

        try:
            with open(model_path, 'rb') as f:
                model_data = pickle.load(f)

            model = model_data['model']
            # 适配实际的模型结构：使用feature_names而不是feature_columns
            feature_columns = model_data.get('feature_names', [])

            if not feature_columns:
                # 如果没有feature_names，尝试从模型对象获取
                if hasattr(model, 'feature_name'):
                    feature_columns = model.feature_name()
                else:
                    logger.error("无法确定模型使用的特征列")
                    print("错误: 无法确定模型使用的特征列")
                    return False

            logger.info(f"成功加载模型，特征数: {len(feature_columns)}")
            print(f"成功加载模型，特征数: {len(feature_columns)}")

        except Exception as e:
            logger.error(f"加载模型失败: {e}")
            print(f"错误: 加载模型失败: {e}")
            return False

        # 3. 数据预处理和行业适配（使用标准化SW编码系统）
        logger.info("步骤3: 数据预处理和行业适配")
        logger.info("[OK] 使用标准化SW行业编码系统")
        processed_data, X_pred = _prepare_prediction_data(factor_data, feature_columns, logger)

        if processed_data is None or X_pred is None:
            logger.error("数据预处理失败")
            print("错误: 数据预处理失败")
            return False

        # 4. 数据过滤（排除不符合交易条件的股票）
        logger.info("步骤4: 数据过滤（排除ST、涨停、跌停、新股等）")
        original_count = len(processed_data)

        try:
            # 4.1 过滤ST股票
            if len(processed_data) > 0:
                st_filter = _filter_st_stocks(processed_data, logger)
                processed_data = processed_data[st_filter].copy()
                st_filtered = original_count - len(processed_data)
                logger.info(f"[过滤] ST股过滤: {original_count} -> {len(processed_data)} (过滤掉 {st_filtered})")
                print(f"[过滤] ST股过滤: {original_count} -> {len(processed_data)} (过滤掉 {st_filtered})")

            # 4.2 过滤T日涨停股票（无法买入）
            if 'is_limit_up' in processed_data.columns and len(processed_data) > 0:
                before_limit_up = len(processed_data)
                processed_data = processed_data[processed_data['is_limit_up'] != 1].copy()
                limit_up_filtered = before_limit_up - len(processed_data)
                logger.info(f"[过滤] 涨停股过滤: {before_limit_up} -> {len(processed_data)} (过滤掉 {limit_up_filtered})")
                print(f"[过滤] 涨停股过滤: {before_limit_up} -> {len(processed_data)} (过滤掉 {limit_up_filtered})")

            # 4.3 过滤T日跌停股票（风险高）
            if 'is_limit_down' in processed_data.columns and len(processed_data) > 0:
                before_limit_down = len(processed_data)
                processed_data = processed_data[processed_data['is_limit_down'] != 1].copy()
                limit_down_filtered = before_limit_down - len(processed_data)
                logger.info(f"[过滤] 跌停股过滤: {before_limit_down} -> {len(processed_data)} (过滤掉 {limit_down_filtered})")
                print(f"[过滤] 跌停股过滤: {before_limit_down} -> {len(processed_data)} (过滤掉 {limit_down_filtered})")

            # 4.4 过滤新股（上市不足30天）
            if len(processed_data) > 0:
                processed_data = _filter_new_stocks_batch(processed_data, logger)
                new_stock_filtered = original_count - len(processed_data) - st_filtered - limit_up_filtered - limit_down_filtered
                logger.info(f"[过滤] 新股过滤完成，剩余股票: {len(processed_data)}")
                print(f"[过滤] 新股过滤完成，剩余股票: {len(processed_data)}")

            # 4.5 流动性过滤（成交额 < 1000万视为流动性不足）
            if 'amount' in processed_data.columns and len(processed_data) > 0:
                before_liquidity = len(processed_data)
                # 成交额单位：元，1000万 = 10,000,000
                liquidity_threshold = 10_000_000
                processed_data = processed_data[processed_data['amount'] >= liquidity_threshold].copy()
                liquidity_filtered = before_liquidity - len(processed_data)
                logger.info(f"[过滤] 流动性过滤(amount): {before_liquidity} -> {len(processed_data)} (过滤掉 {liquidity_filtered})")
                print(f"[过滤] 流动性过滤: {before_liquidity} -> {len(processed_data)} (过滤掉 {liquidity_filtered})")

          
            total_filtered = original_count - len(processed_data)
            filter_rate = total_filtered / original_count * 100 if original_count > 0 else 0
            logger.info(f"[过滤] 数据过滤完成: {original_count} -> {len(processed_data)} (总过滤率 {filter_rate:.1f}%)")
            print(f"[过滤] 数据过滤完成: {original_count} -> {len(processed_data)} (总过滤率 {filter_rate:.1f}%)")

            # 如果过滤后没有股票，提前返回
            if len(processed_data) == 0:
                logger.error("过滤后没有可预测的股票")
                print("错误: 过滤后没有可预测的股票")
                return False

            # 重新提取特征矩阵（因为数据被过滤了）
            X_pred = processed_data[feature_columns]
            logger.info(f"[过滤] 重新提取特征矩阵: {X_pred.shape}")

        except Exception as e:
            logger.error(f"数据过滤失败: {e}")
            print(f"警告: 数据过滤失败，使用原始数据进行预测: {e}")
            # 如果过滤失败，继续使用原始数据

        # 5. 模型预测
        logger.info("步骤5: 执行模型预测")
        try:
            # 预测
            predictions = model.predict(X_pred, num_iteration=model.best_iteration)
            logger.info(f"预测完成，预测值范围: [{predictions.min():.6f}, {predictions.max():.6f}]")

            # 将预测值添加到数据中
            processed_data['prediction'] = predictions

            # 按预测值降序排列
            processed_data = processed_data.sort_values('prediction', ascending=False)

            logger.info(f"预测完成，共预测 {len(predictions)} 只股票")
            print(f"预测完成，共预测 {len(predictions)} 只股票")

        except Exception as e:
            logger.error(f"模型预测失败: {e}")
            print(f"错误: 模型预测失败: {e}")
            return False

        # 6. 输出Top5结果
        logger.info("步骤6: 生成预测结果")
        top5_stocks = processed_data.head(5)

        # 加载SW行业映射用于结果显示
        from sw_encoding_loader import get_sw_mapping_for_model
        sw_mapping = get_sw_mapping_for_model()
        stock_to_industry = sw_mapping.get('stock_to_industry_name', {})

        print(f"\nTop 5 预测结果 ({prediction_date}):")
        print("=" * 80)
        print(f"{'排名':<4} {'股票代码':<12} {'股票名称':<16} {'SW行业':<12} {'预测值':<12}")
        print("-" * 80)

        for rank, (_, row) in enumerate(top5_stocks.iterrows(), 1):
            stock_code = row['stock_code']
            prediction = row['prediction']

            # 获取真实的SW行业名称
            sw_sector_name = stock_to_industry.get(stock_code, '未知')

            print(f"{rank:<4} {stock_code:<12} {'未知':<16} {sw_sector_name:<12} {prediction:<12.6f}")

        print("=" * 80)

        # 7. 保存结果
        results_dir = Path(args.output_dir) if hasattr(args, 'output_dir') and args.output_dir else Path("./results")
        results_dir.mkdir(exist_ok=True)

        result_file = results_dir / f"pred_stocks_{prediction_date}.csv"
        processed_data.to_csv(result_file, index=False, encoding='utf-8-sig')

        logger.info(f"预测结果已保存到: {result_file}")
        print(f"完整预测结果已保存到: {result_file}")

        return True

    except Exception as e:
        logger.error(f"股票预测模式失败: {e}")
        import traceback
        logger.error(f"详细错误: {traceback.format_exc()}")
        print(f"预测失败: {e}")
        return False


def _load_factor_data_for_prediction(prediction_date: str) -> Optional[pd.DataFrame]:
    """
    加载指定日期的因子数据

    Args:
        prediction_date: 预测日期 (YYYYMMDD)

    Returns:
        因子数据DataFrame，或None
    """
    try:
        logger = logging.getLogger(__name__)

        # 使用_load_factor_cache_data加载alpha因子数据
        factor_data = _load_factor_cache_data(
            required_factors=None,  # 加载所有可用因子（包括alpha_XXX系列）
            start_date=prediction_date,
            end_date=prediction_date
        )

        if factor_data is None or factor_data.empty:
            logger.error(f"无法加载 {prediction_date} 的alpha因子数据")
            return None

        # 筛选预测日期的数据
        factor_data['date_str'] = factor_data['date'].dt.strftime('%Y%m%d')
        prediction_data = factor_data[factor_data['date_str'] == prediction_date].copy()

        if prediction_data.empty:
            logger.error(f"因子数据中没有找到 {prediction_date} 的数据")
            return None

        logger.info(f"成功加载 {prediction_date} 的alpha因子数据: {len(prediction_data)} 只股票, {len([col for col in prediction_data.columns if col.startswith('alpha_')])} 个alpha因子")
        return prediction_data

    except Exception as e:
        logger.error(f"加载因子数据失败: {e}")
        import traceback
        logger.error(f"详细错误: {traceback.format_exc()}")
        return None


